/* Déclic — Notions fondamentales : algèbre linéaire (3) : algèbres, produit extérieur, déterminants, cofacteurs */
(()=>{
/* ---------- helpers locaux ---------- */
const M=A=>mat(A.map(r=>r.map(x=>fmt(x))));
const pn=x=>x<0?'('+fmt(x)+')':fmt(x);
const det2=A=>A[0][0]*A[1][1]-A[0][1]*A[1][0];
const det3=A=>A[0][0]*(A[1][1]*A[2][2]-A[1][2]*A[2][1])-A[0][1]*(A[1][0]*A[2][2]-A[1][2]*A[2][0])+A[0][2]*(A[1][0]*A[2][1]-A[1][1]*A[2][0]);
const minor=(A,i,j)=>det2(A.filter((_,r)=>r!==i).map(r=>r.filter((_,c)=>c!==j)));
const cof=(A,i,j)=>((i+j)%2?-1:1)*minor(A,i,j);
const cols=(...v)=>v[0].map((_,i)=>v.map(u=>u[i]));
const ap2=(A,p)=>[A[0][0]*p[0]+A[0][1]*p[1],A[1][0]*p[0]+A[1][1]*p[1]];
const add=(...a)=>a.reduce((s,u)=>s.map((x,i)=>x+u[i]));
const w2=(u,v)=>u[0]*v[1]-u[1]*v[0];
// Parallélogramme orienté construit sur u (bleu) et v (orange) : bleu si u ∧ v > 0, rouge si < 0
function parall(u,v,r=6){
  const P=plane({x:[-r,r],y:[-r,r],lab:2}), w=w2(u,v), col=w>0?'var(--accent)':w<0?'var(--bad)':'var(--muted)';
  if(w!==0) P.poly([[0,0],u,add(u,v),v],{fill:col,fo:.3,c:col,w:2});
  else P.seg(0,0,u[0]+v[0],u[1]+v[1],{c:'var(--muted)',w:2,dash:true});
  P.arrow(0,0,u[0],u[1],{c:'var(--math)'}).arrow(0,0,v[0],v[1],{c:'var(--spark)'});
  P.text(u[0],u[1],'u',{c:'var(--math)',dx:7,dy:-5}).text(v[0],v[1],'v',{c:'var(--spark)',dx:7,dy:-5});
  return P.svg();
}
// Boîte (parallélépipède) construite sur u, v, w dans l’espace
function boite(u,v,w,az=30,r=4.2){
  const S=space({az,r}), O=[0,0,0], bas=[O,u,add(u,v),v], haut=bas.map(p=>add(p,w));
  S.poly(bas,{fill:'var(--sci)',fo:.2,c:'var(--sci)',w:1.5}).poly(haut,{fill:'var(--accent)',fo:.15,c:'var(--accent)',w:1.5});
  bas.forEach((p,i)=>S.seg(p,haut[i],{c:'var(--muted)',w:1.5}));
  S.arrow(O,u,{c:'var(--math)',w:3,hs:8}).arrow(O,v,{c:'var(--math)',w:3,hs:8}).arrow(O,w,{c:'var(--spark)',w:3,hs:8});
  S.text(u,'u',{dx:5,dy:13,c:'var(--math)'}).text(v,'v',{dx:7,c:'var(--math)'}).text(w,'w',{dx:7,dy:-2,c:'var(--spark)'});
  return S.svg();
}
// Quadrillage déformé par une matrice 2 × 2, carré unité et son image
const LSH=[[0,0],[2,0],[2,.7],[.7,.7],[.7,2],[0,2]]; // une forme en L, pour voir l’orientation
function grille2(A,r=4){
  const P=plane({x:[-r,r],y:[-r,r],grid:false}), T=p=>ap2(A,p), d=det2(A), n=3;
  for(let i=-n;i<=n;i++){ const p=T([i,-n]),q=T([i,n]),s=T([-n,i]),t=T([n,i]); P.seg(p[0],p[1],q[0],q[1],{c:'var(--line)',w:1.2}).seg(s[0],s[1],t[0],t[1],{c:'var(--line)',w:1.2}); }
  P.poly([[0,0],[1,0],[1,1],[0,1]],{c:'var(--muted)',w:1.5,dash:true});
  const col=d>0?'var(--accent)':d<0?'var(--bad)':'var(--muted)';
  P.poly([[0,0],T([1,0]),T([1,1]),T([0,1])],{fill:col,fo:.3,c:col,w:2});
  P.arrow(0,0,A[0][0],A[1][0],{c:'var(--math)'}).arrow(0,0,A[0][1],A[1][1],{c:'var(--spark)'});
  P.text(A[0][0],A[1][0],'Ae₁',{c:'var(--math)',dx:6,dy:-4}).text(A[0][1],A[1][1],'Ae₂',{c:'var(--spark)',dx:6,dy:-4});
  return P.svg();
}
function forme(A){
  const P=plane({x:[-4,4],y:[-4,4],lab:2}), d=det2(A), col=d>0?'var(--accent)':d<0?'var(--bad)':'var(--muted)';
  P.poly(LSH,{fill:'var(--muted)',fo:.15,c:'var(--muted)',w:1.5,dash:true});
  P.poly(LSH.map(p=>ap2(A,p)),{fill:col,fo:.35,c:col,w:2});
  return P.svg();
}
// Règle de Sarrus sur une matrice concrète : colonnes 1 et 2 recopiées à droite
const sarrusFig=(()=>{ const A=[[2,1,3],[0,4,1],[5,2,1]], X=k=>38+k*50, Y=r=>42+r*38;
  let s='<svg viewBox="0 0 320 212" width="320" role="img">';
  for(let k=0;k<3;k++){ s+=`<line x1="${X(k)}" y1="${Y(0)}" x2="${X(k+2)}" y2="${Y(2)}" stroke="var(--ok)" stroke-width="4" opacity=".5" stroke-linecap="round"/>`;
    s+=`<line x1="${X(k)}" y1="${Y(2)}" x2="${X(k+2)}" y2="${Y(0)}" stroke="var(--bad)" stroke-width="4" opacity=".5" stroke-linecap="round" stroke-dasharray="6 5"/>`; }
  s+=`<line x1="${X(2)+25}" y1="18" x2="${X(2)+25}" y2="${Y(2)+22}" stroke="var(--muted)" stroke-width="1.5" stroke-dasharray="4 4"/>`;
  for(let r=0;r<3;r++) for(let k=0;k<5;k++) s+=`<text x="${X(k)}" y="${Y(r)+6}" font-size="17" font-weight="700" text-anchor="middle" fill="${k>2?'var(--muted)':'var(--ink)'}" paint-order="stroke" stroke="var(--surface)" stroke-width="4">${A[r][k%3]}</text>`;
  s+=`<text x="160" y="180" font-size="12.5" font-weight="700" text-anchor="middle" fill="var(--ok)">+ 2·4·1 + 1·1·5 + 3·0·2 = 13</text><text x="160" y="202" font-size="12.5" font-weight="700" text-anchor="middle" fill="var(--bad)">− 3·4·5 − 2·1·2 − 1·0·1 = −64</text>`;
  return s+'</svg>'; })();
// Grille 3 × 3 : ligne i et colonne j barrées, le mineur restant en couleur (i, j de 0 à 2)
function mineurFig(A,i,j){
  const cs=44, x0=94, y0=14; let s='<svg viewBox="0 0 320 196" width="320" role="img">';
  for(let r=0;r<3;r++) for(let c=0;c<3;c++){ const x=x0+c*cs, y=y0+r*cs, out=r===i||c===j;
    s+=`<rect x="${x+2}" y="${y+2}" width="${cs-4}" height="${cs-4}" rx="6" fill="${out?'var(--bad)':'var(--accent)'}" fill-opacity="${out?.1:.3}" stroke="${out?'var(--line)':'var(--accent)'}" stroke-width="1.5"/>`;
    s+=`<text x="${x+cs/2}" y="${y+cs/2+6}" font-size="16" font-weight="700" text-anchor="middle" fill="${out?'var(--muted)':'var(--ink)'}">${fmt(A[r][c])}</text>`; }
  s+=`<line x1="${x0-6}" y1="${y0+i*cs+cs/2}" x2="${x0+3*cs+6}" y2="${y0+i*cs+cs/2}" stroke="var(--bad)" stroke-width="3" opacity=".55"/>`;
  s+=`<line x1="${x0+j*cs+cs/2}" y1="${y0-6}" x2="${x0+j*cs+cs/2}" y2="${y0+3*cs+6}" stroke="var(--bad)" stroke-width="3" opacity=".55"/>`;
  s+=`<text x="160" y="${y0+3*cs+28}" font-size="13.5" font-weight="700" text-anchor="middle" fill="var(--ink)">M<tspan font-size="10" baseline-shift="sub">${i+1}${j+1}</tspan> = ${fmt(minor(A,i,j))}, signe ${(i+j)%2?'−':'+'}, C<tspan font-size="10" baseline-shift="sub">${i+1}${j+1}</tspan> = ${fmt(cof(A,i,j))}</text>`;
  return s+'</svg>';
}
const PRESETS=[{n:'quart de tour',A:[[0,-1],[1,0]]},{n:'symétrie d’axe horizontal',A:[[1,0],[0,-1]]},{n:'cisaillement',A:[[1,1],[0,1]]},{n:'homothétie de rapport 1,5',A:[[1.5,0],[0,1.5]]},{n:'étirement-compression',A:[[2,0],[0,.5]]},{n:'projection sur l’axe horizontal',A:[[1,0],[0,0]]}];
const AMIN=[[2,-1,3],[0,4,1],[5,2,-2]];
const damier=mat([['+','−','+'],['−','+','−'],['+','−','+']]);

COURS.push(
/* ===================== 1. ℝ-ALGÈBRES ET ALGÈBRE EXTÉRIEURE ===================== */
{subj:'gred',sem:'lin',id:'gred-algebre',h:'ℝ-algèbres et algèbre extérieure',p:'Un espace vectoriel où l’on sait aussi multiplier : les ℝ-algèbres et leurs axiomes, puis le produit extérieur u ∧ v, aire orientée d’un parallélogramme, et u ∧ v ∧ w, volume orienté, nul exactement quand la famille est liée.',steps:[
  {h:'Un espace vectoriel où l’on multiplie',p:`<div class="blk" data-t="Rappel"><p>Un <b>espace vectoriel</b> réel <i>E</i> est un ensemble où l’on sait additionner deux vecteurs et multiplier un vecteur par un réel, avec les règles habituelles (associativité, commutativité de +, vecteur nul, opposé, distributivités). Une application <i>f</i> : <i>E</i> → <i>F</i> est <b>linéaire</b> si <i>f</i>(λ<i>u</i> + μ<i>v</i>) = λ<i>f</i>(<i>u</i>) + μ<i>f</i>(<i>v</i>).</p></div>
<p>Dans beaucoup d’espaces vectoriels, on dispose en plus d’un <b>produit</b> entre deux vecteurs : on multiplie deux matrices carrées, deux polynômes, deux fonctions. À chaque fois, le produit respecte la structure vectorielle. Pour parler de tous ces cas d’un coup, on introduit une notion commune.</p>
<div class="def"><p>Une <b>ℝ-algèbre associative</b> est un espace vectoriel réel <i>E</i> muni d’un produit <i>E</i> × <i>E</i> → <i>E</i>, (<i>u</i>, <i>v</i>) ↦ <i>u</i> · <i>v</i>, tel que :</p><p>• le produit est <b>bilinéaire</b> : (λ<i>u</i> + μ<i>u</i>′) · <i>v</i> = λ(<i>u</i> · <i>v</i>) + μ(<i>u</i>′ · <i>v</i>) et <i>u</i> · (λ<i>v</i> + μ<i>v</i>′) = λ(<i>u</i> · <i>v</i>) + μ(<i>u</i> · <i>v</i>′) ;</p><p>• le produit est <b>associatif</b> : (<i>u</i> · <i>v</i>) · <i>w</i> = <i>u</i> · (<i>v</i> · <i>w</i>).</p><p>Elle est <b>unitaire</b> s’il existe un élément 1 avec 1 · <i>u</i> = <i>u</i> · 1 = <i>u</i>, et <b>commutative</b> si <i>u</i> · <i>v</i> = <i>v</i> · <i>u</i> pour tous <i>u</i>, <i>v</i>.</p></div>
<div class="idea"><p>« Bilinéaire » signifie : si tu fixes l’un des deux facteurs, l’application qui reste est linéaire. On peut donc développer un produit comme en algèbre élémentaire, en respectant l’ordre des facteurs. Les réels, eux, passent devant : (3<i>u</i>) · (2<i>v</i>) = 6(<i>u</i> · <i>v</i>).</p></div>
<div class="ex"><p>ℝ lui-même est une ℝ-algèbre commutative unitaire de dimension 1. L’ensemble ℂ des nombres complexes, vu comme l’espace vectoriel réel de base (1, <i>i</i>), est une ℝ-algèbre commutative unitaire de dimension 2 : le produit (<i>a</i> + <i>bi</i>)(<i>c</i> + <i>di</i>) est bilinéaire et associatif.</p></div>`,
   note:'Une algèbre unitaire est à la fois un espace vectoriel et un anneau. Les deux structures sont reliées par la bilinéarité : c’est elle qui permet de « sortir » les réels des produits.'},
  {h:'Trois algèbres à connaître',p:`<p>Les exemples qui suivent reviennent dans tout le cours. Chacun est un espace vectoriel déjà connu, et son produit est celui que tu pratiques depuis longtemps.</p>
<div class="ex"><p><b>Les matrices carrées</b> Mₙ(ℝ). L’espace a pour dimension <i>n</i>², le produit est le produit ligne × colonne. Il est bilinéaire, car chaque coefficient du produit est une somme de produits d’un coefficient de chaque facteur. Il est associatif, car il correspond à la composition d’applications linéaires. Le neutre est la matrice identité I. L’algèbre n’est <b>pas commutative</b> dès que <i>n</i> ≥ 2.</p><p><b>Les polynômes</b> ℝ[<i>T</i>]. L’espace est de dimension infinie (la famille 1, <i>T</i>, <i>T</i>², … est libre). Le produit est commutatif, associatif, de neutre le polynôme 1, et un produit de polynômes non nuls n’est jamais nul.</p><p><b>Les fonctions</b> de ℝ dans ℝ. Le produit se fait point par point : (<i>f</i> · <i>g</i>)(<i>x</i>) = <i>f</i>(<i>x</i>)<i>g</i>(<i>x</i>). Il hérite de toutes les propriétés du produit des réels : bilinéaire, associatif, commutatif, de neutre la fonction constante 1. Mais ici <i>f</i> · <i>g</i> peut être nulle sans que <i>f</i> ni <i>g</i> le soit : prends <i>f</i>(<i>x</i>) = max(<i>x</i>, 0) et <i>g</i>(<i>x</i>) = max(−<i>x</i>, 0).</p></div>
<div class="warn"><p>L’associativité ne va pas de soi. Sur ℝ³, le produit vectoriel <i>u</i> × <i>v</i> est bilinéaire, mais (<i>e</i>₁ × <i>e</i>₁) × <i>e</i>₂ = 0 × <i>e</i>₂ = 0 alors que <i>e</i>₁ × (<i>e</i>₁ × <i>e</i>₂) = <i>e</i>₁ × <i>e</i>₃ = −<i>e</i>₂. Les deux parenthésages diffèrent : (ℝ³, ×) n’est pas une algèbre associative.</p></div>`,
   note:'Dans une algèbre, on peut écrire u · v · w sans parenthèses grâce à l’associativité, mais on ne peut pas changer l’ordre des facteurs sans savoir que l’algèbre est commutative.'},
  {kind:'Question',h:'Reconnaître une algèbre',p:'On munit ℝ² de l’un des produits ci-dessous. Lequel fait de ℝ² une ℝ-algèbre associative&nbsp;?',
   opts:['(<i>x</i> ; <i>y</i>) · (<i>x</i>′ ; <i>y</i>′) = (<i>xx</i>′ ; <i>y</i> + <i>y</i>′)','(<i>x</i> ; <i>y</i>) · (<i>x</i>′ ; <i>y</i>′) = (<i>xy</i>′ ; <i>yx</i>′)','(<i>x</i> ; <i>y</i>) · (<i>x</i>′ ; <i>y</i>′) = (<i>xx</i>′ ; <i>yy</i>′)','(<i>x</i> ; <i>y</i>) · (<i>x</i>′ ; <i>y</i>′) = (<i>xx</i>′ + 1 ; <i>yy</i>′)'],ans:2,
   why:'Le produit coordonnée par coordonnée est bilinéaire et associatif, car chaque coordonnée se comporte comme un produit de réels. Le premier n’est pas bilinéaire : la deuxième coordonnée y + y′ ne double pas quand on double le premier facteur. Le deuxième est bilinéaire mais pas associatif : avec u = (1 ; 0), v = (0 ; 1), w = (1 ; 0), on a u · v = (1 ; 0), puis (u · v) · w = (1 ; 0) · (1 ; 0) = (0 ; 0), alors que v · w = (0 ; 1) et u · (v · w) = (1 ; 0) · (0 ; 1) = (1 ; 0). Le dernier n’est pas bilinéaire : 0 · v devrait être nul, or il vaut (1 ; 0).'},
  {kind:'Méthode',h:'Vérifier les axiomes d’une algèbre',
   p:'<b>Quand :</b> on te donne un espace vectoriel et une formule de produit, et on demande si c’est une ℝ-algèbre associative (puis si elle est unitaire, commutative). <b>Pourquoi ça marche :</b> les axiomes d’espace vectoriel sont déjà acquis ; il ne reste que deux choses à contrôler, la bilinéarité et l’associativité. <b>Comment :</b> 1) <b>bilinéarité</b> : fixe le second facteur et vérifie que (λ<i>u</i> + μ<i>u</i>′) · <i>v</i> = λ(<i>u</i> · <i>v</i>) + μ(<i>u</i>′ · <i>v</i>), puis fais de même avec le premier facteur fixé ; en coordonnées, c’est acquis si chaque coordonnée du produit est une somme de termes « un coefficient de <i>u</i> fois un coefficient de <i>v</i> » ; 2) <b>associativité</b> : calcule (<i>u</i> · <i>v</i>) · <i>w</i> et <i>u</i> · (<i>v</i> · <i>w</i>) avec des lettres, et compare ; 3) cherche un <b>neutre</b> en résolvant 1 · <i>u</i> = <i>u</i> ; 4) teste la <b>commutativité</b>. Un seul contre-exemple numérique suffit à réfuter un axiome.',
   demo:{enonce:'Sur ℝ², on pose (<i>a</i> ; <i>b</i>) · (<i>c</i> ; <i>d</i>) = (<i>ac</i> ; <i>ad</i> + <i>bc</i>). Montre que c’est une ℝ-algèbre associative, commutative et unitaire (les « nombres duaux »).',
    etapes:[{f:'Les coordonnées du produit sont <i>ac</i> et <i>ad</i> + <i>bc</i> : chaque terme est un coefficient du premier facteur fois un coefficient du second. Le produit est bilinéaire.',w:'Si on remplace (a ; b) par λ(a ; b) + μ(a′ ; b′), chaque terme se développe linéairement ; de même pour le second facteur.'},
     {f:'((<i>a</i> ; <i>b</i>) · (<i>c</i> ; <i>d</i>)) · (<i>e</i> ; <i>f</i>) = (<i>ac</i> ; <i>ad</i> + <i>bc</i>) · (<i>e</i> ; <i>f</i>) = (<i>ace</i> ; <i>acf</i> + <i>ade</i> + <i>bce</i>).',w:'On applique la formule avec le premier facteur (ac ; ad + bc).'},
     {f:'(<i>a</i> ; <i>b</i>) · ((<i>c</i> ; <i>d</i>) · (<i>e</i> ; <i>f</i>)) = (<i>a</i> ; <i>b</i>) · (<i>ce</i> ; <i>cf</i> + <i>de</i>) = (<i>ace</i> ; <i>acf</i> + <i>ade</i> + <i>bce</i>).',w:'Même résultat : le produit est associatif.'},
     {f:'(1 ; 0) · (<i>c</i> ; <i>d</i>) = (<i>c</i> ; <i>d</i>) : le neutre est (1 ; 0). Et (<i>a</i> ; <i>b</i>) · (<i>c</i> ; <i>d</i>) = (<i>c</i> ; <i>d</i>) · (<i>a</i> ; <i>b</i>) car <i>ad</i> + <i>bc</i> = <i>cb</i> + <i>da</i>.',w:'Commutativité : les formules sont symétriques quand on échange (a ; b) et (c ; d).'},
     {f:'Si on note ε = (0 ; 1), alors ε · ε = (0 · 0 ; 0 · 1 + 1 · 0) = (0 ; 0).',w:'Un élément non nul dont le carré est nul : cette algèbre n’est pas intègre, contrairement à ℂ.'}],
    conclusion:'C’est une ℝ-algèbre associative, commutative et unitaire de dimension 2. On écrit ses éléments <i>a</i> + <i>b</i>ε avec <b>ε² = 0</b>, et on calcule comme avec des polynômes en ε en supprimant tous les termes en ε².'}},
  {h:'Multiplier deux nombres duaux',p:'Dans l’algèbre des nombres duaux, calcule (3 ; 2) · (2 ; −5) et donne sa <b>deuxième</b> coordonnée.',lab:'2e coordonnée =',ans:-11,
   why:'(a ; b) · (c ; d) = (ac ; ad + bc) donne (3 · 2 ; 3 · (−5) + 2 · 2) = (6 ; −11). Avec l’écriture a + bε : (3 + 2ε)(2 − 5ε) = 6 − 15ε + 4ε − 10ε² = 6 − 11ε.'},
  {h:'Le produit extérieur de deux vecteurs',p:`<p>Deux vecteurs <i>u</i> et <i>v</i> du plan sont-ils colinéaires ? Et sinon, « à quel point » ne le sont-ils pas ? La bonne mesure est l’<b>aire du parallélogramme</b> qu’ils déterminent. Pour en faire un objet algébrique, on invente un produit dont le résultat représente ce parallélogramme, avec son orientation.</p>
<div class="def"><p>Le <b>produit extérieur</b> de <i>u</i> et <i>v</i> dans ℝ², noté <i>u</i> ∧ <i>v</i> (on lit « <i>u</i> wedge <i>v</i> »), est un produit à valeurs dans un nouvel espace vectoriel, soumis à deux règles :</p><p>• il est <b>bilinéaire</b> : (λ<i>u</i> + μ<i>u</i>′) ∧ <i>v</i> = λ <i>u</i> ∧ <i>v</i> + μ <i>u</i>′ ∧ <i>v</i>, et de même à droite ;</p><p>• il est <b>alterné</b> : <i>u</i> ∧ <i>u</i> = 0 pour tout vecteur <i>u</i>.</p></div>
<div class="prop"><p>Le produit extérieur est <b>antisymétrique</b> : <i>v</i> ∧ <i>u</i> = −<i>u</i> ∧ <i>v</i>.</p></div>
<div class="why"><p>On développe (<i>u</i> + <i>v</i>) ∧ (<i>u</i> + <i>v</i>) par bilinéarité : <i>u</i> ∧ <i>u</i> + <i>u</i> ∧ <i>v</i> + <i>v</i> ∧ <i>u</i> + <i>v</i> ∧ <i>v</i>. Le membre de gauche est nul (alternance), ainsi que <i>u</i> ∧ <i>u</i> et <i>v</i> ∧ <i>v</i>. Il reste <i>u</i> ∧ <i>v</i> + <i>v</i> ∧ <i>u</i> = 0.</p></div>
<div class="idea"><p>Échanger les deux facteurs retourne le parallélogramme comme une crêpe : même aire, orientation opposée. Et un parallélogramme construit sur deux fois le même vecteur est aplati, d’aire nulle : c’est le sens de <i>u</i> ∧ <i>u</i> = 0.</p></div>
<div class="ex"><p>Avec la base canonique, <i>e</i>₁ ∧ <i>e</i>₂ représente le carré unité orienté dans le sens direct (de <i>e</i>₁ vers <i>e</i>₂). Alors <i>e</i>₂ ∧ <i>e</i>₁ = −<i>e</i>₁ ∧ <i>e</i>₂, et (2<i>e</i>₁) ∧ (3<i>e</i>₂) = 6 <i>e</i>₁ ∧ <i>e</i>₂ : un rectangle 2 × 3, d’aire 6.</p></div>`,
   note:'Le résultat u ∧ v n’est pas un vecteur du plan, ni un nombre : c’est un « bivecteur », un élément d’un nouvel espace. Tu verras à l’étape suivante que cet espace est une droite, ce qui permettra de le confondre avec un nombre.'},
  {h:'L’aire orientée du parallélogramme',p:`<p>Déplace les coordonnées de <i>u</i> (bleu) et <i>v</i> (orange). Le parallélogramme construit sur eux est coloré en bleu quand on tourne de <i>u</i> vers <i>v</i> dans le sens direct (sens inverse des aiguilles d’une montre), en rouge dans le sens indirect. Le nombre affiché est son <b>aire orientée</b> : l’aire, affectée du signe de l’orientation.</p>
<div class="idea"><p>Les deux règles du produit extérieur sont exactement les propriétés de l’aire orientée.</p><p>• <b>Alternance</b> : si <i>v</i> = <i>u</i>, le parallélogramme est écrasé sur une droite, son aire est nulle.</p><p>• <b>Linéarité en <i>v</i></b> : doubler <i>v</i> double l’aire ; et remplacer <i>v</i> par <i>v</i> + λ<i>u</i> fait glisser le côté opposé à <i>u</i> le long de sa propre direction, ce qui conserve l’aire (c’est le principe de Cavalieri : même base, même hauteur). Donc <i>u</i> ∧ (<i>v</i> + λ<i>u</i>) = <i>u</i> ∧ <i>v</i> + λ <i>u</i> ∧ <i>u</i> = <i>u</i> ∧ <i>v</i>.</p></div>
<div class="ex"><p>Essaie <i>u</i> = (3 ; 0) et <i>v</i> = (1 ; 2) : le parallélogramme a pour base 3 et pour hauteur 2, aire 6. Passe à <i>v</i> = (4 ; 2) ou (−2 ; 2) : la hauteur ne change pas, l’aire reste 6. Échange les rôles, <i>u</i> = (1 ; 2) et <i>v</i> = (3 ; 0) : l’aire devient −6.</p></div>`,
   params:[{id:'u1',l:'u₁',min:-4,max:4,v:3},{id:'u2',l:'u₂',min:-4,max:4,v:0},{id:'v1',l:'v₁',min:-4,max:4,v:1},{id:'v2',l:'v₂',min:-4,max:4,v:2}],
   draw:v=>parall([v.u1,v.u2],[v.v1,v.v2]),
   info:v=>{ const w=w2([v.u1,v.u2],[v.v1,v.v2]); return `aire orientée : ${fmt(v.u1)} · ${pn(v.v2)} − ${fmt(v.u2)} · ${pn(v.v1)} = <b>${fmt(w)}</b>`+(w===0?' : u et v sont colinéaires (ou l’un est nul)':w>0?' : orientation directe':' : orientation indirecte'); },
   note:'L’orientation se lit avec la main droite : pouce sur u, index sur v. Si l’index est à gauche du pouce (vu de dessus), l’aire orientée est positive.'},
  {h:'Le calcul en coordonnées',p:`<p>Les deux règles suffisent à calculer n’importe quel produit extérieur dans ℝ². On écrit <i>u</i> = <i>u</i>₁<i>e</i>₁ + <i>u</i>₂<i>e</i>₂ et <i>v</i> = <i>v</i>₁<i>e</i>₁ + <i>v</i>₂<i>e</i>₂, puis on développe.</p>
<div class="thm"><p>Pour tous <i>u</i>, <i>v</i> ∈ ℝ² :</p><p><b><i>u</i> ∧ <i>v</i> = (<i>u</i>₁<i>v</i>₂ − <i>u</i>₂<i>v</i>₁) <i>e</i>₁ ∧ <i>e</i>₂</b>.</p><p>Tous les produits extérieurs sont donc des multiples de <i>e</i>₁ ∧ <i>e</i>₂ : l’espace qu’ils engendrent, noté Λ²(ℝ²), est une <b>droite vectorielle</b>. Le nombre <i>u</i>₁<i>v</i>₂ − <i>u</i>₂<i>v</i>₁ est l’aire orientée du parallélogramme.</p></div>
<div class="why"><p>Par bilinéarité, <i>u</i> ∧ <i>v</i> = <i>u</i>₁<i>v</i>₁ <i>e</i>₁ ∧ <i>e</i>₁ + <i>u</i>₁<i>v</i>₂ <i>e</i>₁ ∧ <i>e</i>₂ + <i>u</i>₂<i>v</i>₁ <i>e</i>₂ ∧ <i>e</i>₁ + <i>u</i>₂<i>v</i>₂ <i>e</i>₂ ∧ <i>e</i>₂. Les deux termes <i>e</i>₁ ∧ <i>e</i>₁ et <i>e</i>₂ ∧ <i>e</i>₂ sont nuls (alternance), et <i>e</i>₂ ∧ <i>e</i>₁ = −<i>e</i>₁ ∧ <i>e</i>₂ (antisymétrie). On regroupe.</p></div>
<div class="prop"><p><i>u</i> ∧ <i>v</i> = 0 si et seulement si la famille (<i>u</i>, <i>v</i>) est <b>liée</b>.</p></div>
<div class="why"><p>Si <i>v</i> = λ<i>u</i>, alors <i>u</i> ∧ <i>v</i> = λ <i>u</i> ∧ <i>u</i> = 0 (et de même si <i>u</i> = λ<i>v</i>). Réciproquement, supposons <i>u</i>₁<i>v</i>₂ − <i>u</i>₂<i>v</i>₁ = 0 avec <i>u</i> ≠ 0, disons <i>u</i>₁ ≠ 0. Posons λ = <i>v</i>₁/<i>u</i>₁. Alors <i>v</i>₁ = λ<i>u</i>₁, et <i>v</i>₂ = <i>u</i>₂<i>v</i>₁/<i>u</i>₁ = λ<i>u</i>₂ : donc <i>v</i> = λ<i>u</i>.</p></div>
<div class="ex"><p><i>u</i> = (2 ; 1), <i>v</i> = (1 ; 3) : <i>u</i> ∧ <i>v</i> = (2 · 3 − 1 · 1) <i>e</i>₁ ∧ <i>e</i>₂ = 5 <i>e</i>₁ ∧ <i>e</i>₂. Famille libre, aire 5, orientation directe.</p></div>`},
  {kind:'Méthode',h:'Calculer u ∧ v et tester la liberté',
   p:'<b>Quand :</b> pour calculer une aire orientée, décider si deux vecteurs du plan sont colinéaires, ou savoir si trois points sont alignés (on prend deux vecteurs issus du même point). <b>Pourquoi ça marche :</b> <i>u</i> ∧ <i>v</i> = (<i>u</i>₁<i>v</i>₂ − <i>u</i>₂<i>v</i>₁) <i>e</i>₁ ∧ <i>e</i>₂, et ce coefficient est nul exactement quand la famille est liée. <b>Comment :</b> 1) écris les coordonnées en colonnes côte à côte ; 2) calcule « produit en descendant » moins « produit en montant » : <i>u</i>₁<i>v</i>₂ − <i>u</i>₂<i>v</i>₁, en soignant les signes ; 3) conclus : coefficient non nul, famille libre, aire égale à sa valeur absolue, orientation donnée par son signe ; coefficient nul, famille liée, et on peut chercher λ avec <i>v</i> = λ<i>u</i>.',
   demo:{enonce:'a) <i>u</i> = (3 ; 1) et <i>v</i> = (−2 ; 4). b) <i>u</i> = (2 ; −6) et <i>v</i> = (−1 ; 3). Dans chaque cas, calcule <i>u</i> ∧ <i>v</i> et conclus.',
    etapes:[{f:'a) <i>u</i>₁<i>v</i>₂ − <i>u</i>₂<i>v</i>₁ = 3 · 4 − 1 · (−2) = 12 + 2 = 14.',w:'Produit en descendant 3 · 4, moins produit en montant 1 · (−2). Attention au double signe moins.'},
     {f:'a) <i>u</i> ∧ <i>v</i> = 14 <i>e</i>₁ ∧ <i>e</i>₂ : la famille est libre, le parallélogramme a une aire de 14 et l’orientation de (<i>u</i>, <i>v</i>) est directe.',w:'Coefficient positif : on tourne de u vers v dans le sens direct.'},
     {f:'b) <i>u</i>₁<i>v</i>₂ − <i>u</i>₂<i>v</i>₁ = 2 · 3 − (−6) · (−1) = 6 − 6 = 0.',w:'Le produit en montant vaut (−6)(−1) = +6, qu’on retranche.'},
     {f:'b) <i>u</i> ∧ <i>v</i> = 0 : la famille est liée. On trouve <i>v</i> = −½ <i>u</i>, car (−1 ; 3) = −½ (2 ; −6).',w:'λ = v₁/u₁ = −1/2, et on vérifie sur la deuxième coordonnée : −½ · (−6) = 3.'}],
    conclusion:'a) <b><i>u</i> ∧ <i>v</i> = 14 <i>e</i>₁ ∧ <i>e</i>₂</b>, famille libre. b) <b><i>u</i> ∧ <i>v</i> = 0</b>, famille liée avec <i>v</i> = −½ <i>u</i>. Le même calcul dit si trois points <i>A</i>, <i>B</i>, <i>C</i> sont alignés : c’est le cas quand <i>AB</i> ∧ <i>AC</i> = 0.'}},
  {kind:'Pratique',h:'Aplatis le parallélogramme',p:'Le vecteur <i>u</i> = (2 ; 1) est fixé. Règle <i>v</i> = (<i>a</i> ; <i>b</i>), <b>non nul</b>, pour que <i>u</i> ∧ <i>v</i> = 0. Observe que toutes les solutions sont sur une même droite.',
   params:[{id:'a',l:'a',min:-4,max:4,v:1},{id:'b',l:'b',min:-4,max:4,v:2}],
   draw:v=>parall([2,1],[v.a,v.b],5),
   info:v=>`u ∧ v = (2 · ${pn(v.b)} − 1 · ${pn(v.a)}) e₁ ∧ e₂ = <b>${fmt(2*v.b-v.a)}</b> e₁ ∧ e₂`,
   ok:v=>2*v.b-v.a===0&&(v.a!==0||v.b!==0),
   why:'u ∧ v = (2b − a) e₁ ∧ e₂ est nul quand a = 2b : v = (2 ; 1), (4 ; 2), (−2 ; −1), (−4 ; −2) conviennent. Ce sont les multiples de u : v = λu, le parallélogramme est écrasé sur la droite dirigée par u.'},
  {h:'Un coefficient à calculer',p:'Pour <i>u</i> = (−3 ; 5) et <i>v</i> = (4 ; 2), on a <i>u</i> ∧ <i>v</i> = <i>k</i> <i>e</i>₁ ∧ <i>e</i>₂. Que vaut <i>k</i>&nbsp;?',lab:'k =',ans:-26,
   why:'k = u₁v₂ − u₂v₁ = (−3) · 2 − 5 · 4 = −6 − 20 = −26. L’aire du parallélogramme vaut 26 et l’orientation de (u, v) est indirecte.'},
  {h:'Trois vecteurs de ℝ³ : u ∧ v ∧ w',p:`<p>Dans l’espace, trois vecteurs <i>u</i>, <i>v</i>, <i>w</i> déterminent une boîte, le <b>parallélépipède</b> construit sur eux. Son volume mesure « à quel point » la famille n’est pas coplanaire. On définit le produit extérieur de trois vecteurs avec les mêmes deux règles.</p>
<div class="def"><p>Le produit <i>u</i> ∧ <i>v</i> ∧ <i>w</i> de trois vecteurs de ℝ³ est <b>trilinéaire</b> (linéaire en chacun des trois facteurs quand on fixe les deux autres) et <b>alterné</b> : il est nul dès que deux des trois facteurs sont égaux. Comme en dimension 2, échanger deux facteurs change le signe. L’élément <i>e</i>₁ ∧ <i>e</i>₂ ∧ <i>e</i>₃ représente le cube unité orienté, et</p><p><b><i>u</i> ∧ <i>v</i> ∧ <i>w</i> = (volume orienté de la boîte) · <i>e</i>₁ ∧ <i>e</i>₂ ∧ <i>e</i>₃</b>.</p></div>
<div class="idea"><p>Le volume est orienté : positif si (<i>u</i>, <i>v</i>, <i>w</i>) est une base <b>directe</b> (règle des trois doigts de la main droite), négatif sinon. Et comme pour l’aire, remplacer <i>w</i> par <i>w</i> + λ<i>u</i> + μ<i>v</i> fait glisser le couvercle de la boîte parallèlement à sa base : le volume ne change pas.</p></div>
<div class="ex"><p>Sur la figure, <i>u</i> = (2 ; 0 ; 0) et <i>v</i> = (0 ; 2 ; 0) sont fixés et tu règles <i>w</i> = (<i>a</i> ; 1 ; <i>h</i>). La base a une aire de 4 et la hauteur vaut <i>h</i> : le volume orienté est 4<i>h</i>. Changer <i>a</i> penche la boîte sans rien changer au volume. Pour <i>h</i> = 0, <i>w</i> est dans le plan de la base : la boîte est aplatie.</p></div>`,
   params:[{id:'h',l:'cote h de w',min:-2,max:3,step:.5,v:1.5},{id:'a',l:'abscisse a de w',min:-1,max:2,step:.5,v:0},{id:'az',l:'vue (rotation)',min:0,max:90,step:15,v:30,u:'°'}],
   draw:v=>boite([2,0,0],[0,2,0],[v.a,1,v.h],v.az,3.8),
   info:v=>`u ∧ v ∧ w = 2 · 2 · ${pn(v.h)} e₁ ∧ e₂ ∧ e₃ = <b>${fmt(4*v.h)}</b> e₁ ∧ e₂ ∧ e₃`+(v.h===0?' : boîte aplatie, famille liée':v.h<0?' : base indirecte':' : base directe'),
   note:'On note Λ³(ℝ³) l’espace des produits u ∧ v ∧ w. Comme Λ²(ℝ²), c’est une droite, engendrée par e₁ ∧ e₂ ∧ e₃. L’étape suivante donne la formule qui le prouve.'},
  {kind:'Méthode',h:'Développer u ∧ v ∧ w en coordonnées',
   p:'<b>Quand :</b> pour calculer le volume orienté d’une boîte, ou tester si trois vecteurs de ℝ³ sont coplanaires. <b>Pourquoi ça marche :</b> on développe par trilinéarité ; sur les 27 termes <i>u</i>ᵢ<i>v</i>ⱼ<i>w</i>ₖ <i>e</i>ᵢ ∧ <i>e</i>ⱼ ∧ <i>e</i>ₖ, seuls ceux où <i>i</i>, <i>j</i>, <i>k</i> sont <b>tous différents</b> survivent (sinon deux facteurs sont égaux), soit 6 termes, et chacun se ramène à ±<i>e</i>₁ ∧ <i>e</i>₂ ∧ <i>e</i>₃ en comptant les échanges. On obtient :<br><b><i>u</i> ∧ <i>v</i> ∧ <i>w</i> = (<i>u</i>₁<i>v</i>₂<i>w</i>₃ − <i>u</i>₁<i>v</i>₃<i>w</i>₂ − <i>u</i>₂<i>v</i>₁<i>w</i>₃ + <i>u</i>₂<i>v</i>₃<i>w</i>₁ + <i>u</i>₃<i>v</i>₁<i>w</i>₂ − <i>u</i>₃<i>v</i>₂<i>w</i>₁) <i>e</i>₁ ∧ <i>e</i>₂ ∧ <i>e</i>₃</b>.<br><b>Comment :</b> 1) range les six produits dans cet ordre, avec leurs signes (+ − − + + −) ; 2) calcule chacun à part ; 3) additionne, puis conclus sur le volume et l’orientation.',
   demo:{enonce:'Calcule <i>u</i> ∧ <i>v</i> ∧ <i>w</i> pour <i>u</i> = (1 ; 1 ; 0), <i>v</i> = (0 ; 1 ; 1) et <i>w</i> = (1 ; 0 ; 2).',
    etapes:[{f:'<i>u</i>₁<i>v</i>₂<i>w</i>₃ = 1 · 1 · 2 = 2 et −<i>u</i>₁<i>v</i>₃<i>w</i>₂ = −1 · 1 · 0 = 0.',w:'Les deux termes qui commencent par u₁.'},
     {f:'−<i>u</i>₂<i>v</i>₁<i>w</i>₃ = −1 · 0 · 2 = 0 et +<i>u</i>₂<i>v</i>₃<i>w</i>₁ = 1 · 1 · 1 = 1.',w:'Les deux termes en u₂.'},
     {f:'+<i>u</i>₃<i>v</i>₁<i>w</i>₂ = 0 et −<i>u</i>₃<i>v</i>₂<i>w</i>₁ = 0.',w:'u₃ = 0 tue les deux derniers termes.'},
     {f:'Total : 2 + 0 + 0 + 1 + 0 + 0 = 3.',w:'On additionne les six contributions signées.'}],
    conclusion:'<b><i>u</i> ∧ <i>v</i> ∧ <i>w</i> = 3 <i>e</i>₁ ∧ <i>e</i>₂ ∧ <i>e</i>₃</b> : la boîte a un volume de 3, la base (<i>u</i>, <i>v</i>, <i>w</i>) est directe, et les trois vecteurs ne sont pas coplanaires. Dans le chapitre suivant, ce nombre s’appellera le déterminant de la matrice dont les colonnes sont <i>u</i>, <i>v</i>, <i>w</i>.'}},
  {h:'Nul si et seulement si lié',p:`<p>Le produit extérieur a été construit pour détecter la dépendance linéaire. Voici le théorème qui le dit, en dimension 3 comme en dimension 2.</p>
<div class="thm"><p>Pour trois vecteurs <i>u</i>, <i>v</i>, <i>w</i> de ℝ³ :</p><p><b><i>u</i> ∧ <i>v</i> ∧ <i>w</i> = 0 ⇔ la famille (<i>u</i>, <i>v</i>, <i>w</i>) est liée</b> (les trois vecteurs sont coplanaires).</p></div>
<div class="why"><p><b>Sens ⇐.</b> Si la famille est liée, l’un des vecteurs est combinaison des deux autres, disons <i>w</i> = α<i>u</i> + β<i>v</i>. Alors <i>u</i> ∧ <i>v</i> ∧ <i>w</i> = α <i>u</i> ∧ <i>v</i> ∧ <i>u</i> + β <i>u</i> ∧ <i>v</i> ∧ <i>v</i> = 0 + 0 : chaque terme contient deux facteurs égaux.</p><p><b>Sens ⇒.</b> Supposons la famille libre. Trois vecteurs libres de ℝ³ forment une base, donc chaque <i>e</i>ᵢ s’écrit comme combinaison de <i>u</i>, <i>v</i>, <i>w</i>. En développant <i>e</i>₁ ∧ <i>e</i>₂ ∧ <i>e</i>₃ par trilinéarité, tous les termes contiennent soit deux facteurs égaux (donc nuls), soit <i>u</i>, <i>v</i>, <i>w</i> dans un certain ordre (donc ± <i>u</i> ∧ <i>v</i> ∧ <i>w</i>). Ainsi <i>e</i>₁ ∧ <i>e</i>₂ ∧ <i>e</i>₃ = <i>c</i> · <i>u</i> ∧ <i>v</i> ∧ <i>w</i> pour un réel <i>c</i>. Comme <i>e</i>₁ ∧ <i>e</i>₂ ∧ <i>e</i>₃ ≠ 0 (c’est le cube unité), <i>u</i> ∧ <i>v</i> ∧ <i>w</i> ≠ 0.</p></div>
<div class="ex"><p><i>u</i> = (1 ; 0 ; 0), <i>v</i> = (0 ; 1 ; 0), <i>w</i> = (1 ; 1 ; 0) : la formule donne 1 · 1 · 0 − 0 − 0 + 0 + 0 − 0 = 0, et en effet <i>w</i> = <i>u</i> + <i>v</i>. Avec <i>w</i> = (1 ; 1 ; 1), le premier terme devient 1 · 1 · 1 = 1 et tous les autres restent nuls : volume 1, famille libre.</p></div>`,
   note:'Ce théorème est la clé du chapitre suivant : il deviendra « det A ≠ 0 ⇔ les colonnes de A sont libres ⇔ A est inversible ».'},
  {h:'Trois vecteurs, un volume',p:'Pour <i>u</i> = (1 ; 2 ; 0), <i>v</i> = (0 ; 1 ; 1) et <i>w</i> = (2 ; 0 ; 1), on a <i>u</i> ∧ <i>v</i> ∧ <i>w</i> = <i>k</i> <i>e</i>₁ ∧ <i>e</i>₂ ∧ <i>e</i>₃. Que vaut <i>k</i>&nbsp;?',lab:'k =',ans:5,
   why:'u₁v₂w₃ = 1 · 1 · 1 = 1 ; −u₁v₃w₂ = −1 · 1 · 0 = 0 ; −u₂v₁w₃ = 0 ; +u₂v₃w₁ = 2 · 1 · 2 = 4 ; +u₃v₁w₂ = 0 ; −u₃v₂w₁ = 0. Total k = 5 : la boîte a un volume de 5 et la famille est libre.'},
  {kind:'Récapitulatif',h:'Ce qu’il faut retenir',p:`<div class="keep"><ul>
<li>Une <b>ℝ-algèbre associative</b> est un espace vectoriel muni d’un produit bilinéaire et associatif. Exemples : Mₙ(ℝ) (non commutative), ℝ[<i>T</i>], les fonctions ℝ → ℝ, ℂ, les nombres duaux <i>a</i> + <i>b</i>ε avec ε² = 0. Contre-exemple : (ℝ³, ×) n’est pas associative.</li>
<li>Pour vérifier les axiomes : bilinéarité (chaque coordonnée du produit est une somme de « coefficient de <i>u</i> × coefficient de <i>v</i> »), puis associativité avec des lettres, puis neutre et commutativité.</li>
<li>Le <b>produit extérieur</b> <i>u</i> ∧ <i>v</i> est bilinéaire et alterné (<i>u</i> ∧ <i>u</i> = 0), donc antisymétrique (<i>v</i> ∧ <i>u</i> = −<i>u</i> ∧ <i>v</i>).</li>
<li>Dans ℝ² : <b><i>u</i> ∧ <i>v</i> = (<i>u</i>₁<i>v</i>₂ − <i>u</i>₂<i>v</i>₁) <i>e</i>₁ ∧ <i>e</i>₂</b>. Le coefficient est l’<b>aire orientée</b> du parallélogramme (positive si (<i>u</i>, <i>v</i>) est directe).</li>
<li>Dans ℝ³ : <i>u</i> ∧ <i>v</i> ∧ <i>w</i> = (six termes signés) <i>e</i>₁ ∧ <i>e</i>₂ ∧ <i>e</i>₃, dont le coefficient est le <b>volume orienté</b> de la boîte.</li>
<li><b>Produit extérieur nul ⇔ famille liée.</b> Deux vecteurs colinéaires aplatissent le parallélogramme ; trois vecteurs coplanaires aplatissent la boîte.</li>
</ul></div>`},
  {kind:'Problème',h:'L’aire d’un triangle et un point aligné',
   p:'Dans le plan, on donne les points <i>A</i>(1 ; 1), <i>B</i>(5 ; 2) et <i>C</i>(2 ; 6). Un triangle est la moitié du parallélogramme construit sur deux de ses côtés issus d’un même sommet, donc son aire vaut la moitié de |<i>AB</i> ∧ <i>AC</i>|. On veut l’aire de <i>ABC</i>, l’orientation du parcours <i>A</i> → <i>B</i> → <i>C</i>, puis l’abscisse du point <i>D</i>(<i>x</i> ; 3) situé sur la droite (<i>AB</i>).',
   fig:(()=>{ const P=plane({x:[-1,10],y:[-1,8],lab:2}); P.poly([[1,1],[5,2],[2,6]],{fill:'var(--accent)',fo:.3,c:'var(--accent)',w:2}); P.seg(-1,0.5,10,3.25,{c:'var(--muted)',w:1.5,dash:true}); P.dot(1,1,{l:'A',dx:-16,dy:14}).dot(5,2,{l:'B'}).dot(2,6,{l:'C'}).dot(9,3,{c:'var(--bad)',l:'D(x ; 3)',dx:-30,dy:-12}); return P.svg(); })(),
   parts:[
    {q:'a) Calcule le coefficient <i>k</i> tel que <i>AB</i> ∧ <i>AC</i> = <i>k</i> <i>e</i>₁ ∧ <i>e</i>₂.',lab:'k =',ans:19,hint:'AB = (5 − 1 ; 2 − 1) et AC = (2 − 1 ; 6 − 1). Puis u₁v₂ − u₂v₁.',why:'AB = (4 ; 1), AC = (1 ; 5) : k = 4 · 5 − 1 · 1 = 19.'},
    {q:'b) Quelle est l’aire du triangle <i>ABC</i>&nbsp;?',lab:'aire =',ans:9.5,tol:.01,hint:'La moitié de la valeur absolue du coefficient.',why:'Aire = |19|/2 = 9,5.'},
    {q:'c) Le parcours <i>A</i> → <i>B</i> → <i>C</i> se fait…',opts:['dans le sens direct, car AB ∧ AC a un coefficient positif','dans le sens indirect, car AB ∧ AC a un coefficient positif','dans le sens direct, car l’aire est positive','on ne peut pas le savoir sans dessin'],ans:0,hint:'Le signe du coefficient donne l’orientation du couple (AB, AC). Une aire est toujours positive : elle ne dit rien sur le sens.',why:'k = 19 > 0 : on tourne de AB vers AC dans le sens direct (inverse des aiguilles d’une montre). L’aire, toujours positive, ne porte aucune information d’orientation.'},
    {q:'d) Pour quelle abscisse <i>x</i> le point <i>D</i>(<i>x</i> ; 3) est-il sur la droite (<i>AB</i>)&nbsp;?',lab:'x =',ans:9,hint:'D est sur (AB) ⇔ AB et AD sont colinéaires ⇔ AB ∧ AD = 0. Écris AD en fonction de x.',why:'AD = (x − 1 ; 2). AB ∧ AD = 4 · 2 − 1 · (x − 1) = 9 − x. Il est nul pour x = 9.'},
   ],
   sol:'AB = (4 ; 1) et AC = (1 ; 5), donc <b>AB ∧ AC = (4 · 5 − 1 · 1) e₁ ∧ e₂ = 19 e₁ ∧ e₂</b>.<br>L’aire du parallélogramme construit sur AB et AC vaut 19, celle du triangle <b>9,5</b>. Le coefficient est positif : le couple (AB, AC) est direct, donc le parcours A → B → C se fait dans le sens inverse des aiguilles d’une montre.<br>Pour D(x ; 3) : AD = (x − 1 ; 2) et AB ∧ AD = (4 · 2 − 1 · (x − 1)) e₁ ∧ e₂ = (9 − x) e₁ ∧ e₂. Les vecteurs AB et AD sont colinéaires si et seulement si ce coefficient est nul : <b>x = 9</b>. Contrôle : D(9 ; 3) vérifie AD = (8 ; 2) = 2 · AB.'},
  {kind:'Problème',h:'Les nombres duaux calculent une dérivée',
   p:'Dans l’algèbre des nombres duaux, on écrit <i>a</i> + <i>b</i>ε avec ε² = 0, et on calcule comme avec des polynômes en ε en effaçant les termes en ε². On va voir que le coefficient de ε dans (<i>a</i> + ε)ⁿ est exactement la dérivée de <i>x</i>ⁿ en <i>a</i>, puis chercher quels nombres duaux ont un inverse.',
   parts:[
    {q:'a) Développe (2 + ε)². Quel est le coefficient de ε&nbsp;?',lab:'coefficient de ε :',ans:4,hint:'(2 + ε)(2 + ε) par bilinéarité, puis ε² = 0.',why:'(2 + ε)² = 4 + 2ε + 2ε + ε² = 4 + 4ε. Le coefficient 4 est bien la dérivée de x² en 2.'},
    {q:'b) Développe (2 + ε)³. Quel est le coefficient de ε&nbsp;?',lab:'coefficient de ε :',ans:12,hint:'(2 + ε)³ = (4 + 4ε)(2 + ε).',why:'(4 + 4ε)(2 + ε) = 8 + 4ε + 8ε + 4ε² = 8 + 12ε. Et la dérivée de x³ en 2 vaut 3 · 2² = 12.'},
    {q:'c) Quelle formule générale obtient-on, et pourquoi&nbsp;?',opts:['(a + ε)ⁿ = aⁿ + n aⁿ⁻¹ ε, car en développant le produit de n facteurs, les termes avec au moins deux ε sont nuls, et il y a n façons de choisir le facteur qui donne ε','(a + ε)ⁿ = aⁿ + ε, car ε est négligeable','(a + ε)ⁿ = aⁿ + aⁿ⁻¹ ε, car ε² = 0','(a + ε)ⁿ = (a + 1)ⁿ ε, car on peut remplacer ε par 1'],ans:0,hint:'Développe (a + ε)(a + ε)…(a + ε) : chaque terme choisit a ou ε dans chaque facteur. Combien de termes contiennent exactement un ε ?',why:'Par associativité et bilinéarité, le produit des n facteurs se développe en 2ⁿ termes. Ceux qui contiennent au moins deux ε sont nuls. Il reste aⁿ (aucun ε) et n termes aⁿ⁻¹ε (un seul ε, choisi parmi n facteurs). Le coefficient n aⁿ⁻¹ est la dérivée de xⁿ.'},
    {q:'d) Cherche l’inverse de 2 + 3ε, c’est-à-dire <i>x</i> + <i>y</i>ε tel que (2 + 3ε)(<i>x</i> + <i>y</i>ε) = 1. Que vaut <i>y</i>&nbsp;?',lab:'y =',ans:-0.75,tol:.001,hint:'Développe : la partie sans ε doit valoir 1, le coefficient de ε doit valoir 0.',why:'(2 + 3ε)(x + yε) = 2x + (2y + 3x)ε. Il faut 2x = 1, donc x = 1/2, puis 2y + 3/2 = 0, donc y = −3/4 = −0,75.'},
    {q:'e) Le nombre dual 3ε a-t-il un inverse&nbsp;?',opts:['Oui, c’est ε/3.','Oui, c’est 1/(3ε).','Non : tout produit 3ε · (x + yε) = 3xε a une partie sans ε nulle, il ne peut pas valoir 1.','Non, car 3ε est nul.'],ans:2,hint:'Calcule 3ε · (x + yε) et regarde sa partie sans ε.',why:'3ε(x + yε) = 3xε + 3yε² = 3xε. Sa partie « réelle » est 0, jamais 1. Pourtant 3ε ≠ 0 : c’est un élément non nul et non inversible, impossible dans ℂ.'},
   ],
   sol:'Dans les nombres duaux, (2 + ε)² = 4 + 4ε et (2 + ε)³ = 8 + 12ε. Plus généralement, en développant (a + ε)ⁿ par bilinéarité et associativité, seuls survivent le terme aⁿ et les n termes avec un seul ε : <b>(a + ε)ⁿ = aⁿ + n aⁿ⁻¹ ε</b>. Le coefficient de ε est la dérivée de xⁿ en a : les nombres duaux « dérivent automatiquement ».<br>Pour l’inverse de 2 + 3ε, on résout (2 + 3ε)(x + yε) = 2x + (3x + 2y)ε = 1 : x = 1/2 et y = −3/4. Donc <b>(2 + 3ε)⁻¹ = ½ − ¾ ε</b>. Plus généralement, a + bε est inversible si et seulement si a ≠ 0, d’inverse (1/a) − (b/a²) ε.<br>Enfin 3ε n’est pas inversible : 3ε(x + yε) = 3xε n’a jamais de partie réelle égale à 1. Cette algèbre contient donc des éléments non nuls non inversibles, dont le carré est nul : ce n’est pas un corps.'},
]},

/* ===================== 2. LE DÉTERMINANT ===================== */
{subj:'gred',sem:'lin',id:'gred-determinant',h:'Le déterminant',p:'Le déterminant d’une matrice carrée défini comme coefficient de l’algèbre extérieure, les formules 2 × 2 et 3 × 3 (Sarrus), son sens géométrique (facteur d’aire ou de volume, orientation), ses règles de calcul démontrées, det(AB) = det A · det B et le critère d’inversibilité.',steps:[
  {h:'Le déterminant, coefficient de l’algèbre extérieure',p:`<div class="blk" data-t="Rappel"><p>Une matrice carrée <i>A</i> de taille <i>n</i> représente une application linéaire de ℝⁿ dans ℝⁿ. Sa <i>j</i>-ième colonne est l’image <i>Ae</i>ⱼ du <i>j</i>-ième vecteur de la base canonique.</p></div>
<p>Que fait une matrice au carré unité ? Elle l’envoie sur le parallélogramme construit sur <i>Ae</i>₁ et <i>Ae</i>₂. L’aire orientée de ce parallélogramme est le coefficient de <i>Ae</i>₁ ∧ <i>Ae</i>₂ sur <i>e</i>₁ ∧ <i>e</i>₂. Ce nombre mérite un nom.</p>
<div class="def"><p>Le <b>déterminant</b> d’une matrice carrée <i>A</i> de taille <i>n</i>, noté det <i>A</i> ou |<i>A</i>|, est l’unique réel tel que</p><p><b><i>Ae</i>₁ ∧ <i>Ae</i>₂ ∧ … ∧ <i>Ae</i>ₙ = det(<i>A</i>) · <i>e</i>₁ ∧ <i>e</i>₂ ∧ … ∧ <i>e</i>ₙ</b>.</p><p>Autrement dit, det <i>A</i> est le coefficient du produit extérieur des <b>colonnes</b> de <i>A</i>. On parle aussi du déterminant d’une famille de <i>n</i> vecteurs de ℝⁿ : c’est celui de la matrice qui les a pour colonnes.</p></div>
<div class="idea"><p>Pour <i>n</i> = 2, det <i>A</i> est l’aire orientée du parallélogramme image du carré unité ; pour <i>n</i> = 3, le volume orienté de l’image du cube unité. Sur la figure, règle les quatre coefficients : le carré unité (pointillé) devient le parallélogramme coloré, bleu si l’orientation est conservée, rouge si elle est renversée. Tout le quadrillage se déforme de la même façon.</p></div>
<div class="ex"><p>Pour la matrice identité I, les colonnes sont <i>e</i>₁, …, <i>e</i>ₙ eux-mêmes : <b>det I = 1</b>. Pour <i>A</i> = ${mat([[2,0],[0,3]])}, <i>Ae</i>₁ ∧ <i>Ae</i>₂ = (2<i>e</i>₁) ∧ (3<i>e</i>₂) = 6 <i>e</i>₁ ∧ <i>e</i>₂ : det <i>A</i> = 6, l’aire du carré unité est multipliée par 6.</p></div>`,
   params:[{id:'a',l:'a',min:-2,max:2,step:.5,v:1},{id:'b',l:'b',min:-2,max:2,step:.5,v:1},{id:'c',l:'c',min:-2,max:2,step:.5,v:0},{id:'d',l:'d',min:-2,max:2,step:.5,v:1.5}],
   draw:v=>grille2([[v.a,v.b],[v.c,v.d]]),
   info:v=>{ const d=det2([[v.a,v.b],[v.c,v.d]]); return `${M([[v.a,v.b],[v.c,v.d]])} &nbsp; Ae₁ ∧ Ae₂ = (${fmt(v.a)} · ${pn(v.d)} − ${fmt(v.c)} · ${pn(v.b)}) e₁ ∧ e₂ : det A = <b>${fmt(d)}</b>`+(d===0?' (le plan est aplati)':d<0?' (orientation renversée)':''); },
   note:'Essaie a = d = 0, b = 1, c = 1 : la matrice échange e₁ et e₂, le carré est le même mais parcouru dans l’autre sens, det = −1.'},
  {h:'La formule 2 × 2',p:`<p>La définition devient une formule dès qu’on développe le produit extérieur des colonnes, comme au chapitre précédent.</p>
<div class="thm"><p>Pour <i>A</i> = ${mat([['<i>a</i>','<i>b</i>'],['<i>c</i>','<i>d</i>']])}, &nbsp; <b>det <i>A</i> = <i>ad</i> − <i>bc</i></b>. On l’écrit aussi |<i>A</i>|, ou en remplaçant les parenthèses du tableau par deux barres verticales.</p></div>
<div class="why"><p>Les colonnes sont <i>Ae</i>₁ = (<i>a</i> ; <i>c</i>) = <i>a</i><i>e</i>₁ + <i>c</i><i>e</i>₂ et <i>Ae</i>₂ = (<i>b</i> ; <i>d</i>) = <i>b</i><i>e</i>₁ + <i>d</i><i>e</i>₂. Par bilinéarité et alternance, <i>Ae</i>₁ ∧ <i>Ae</i>₂ = <i>ad</i> <i>e</i>₁ ∧ <i>e</i>₂ + <i>cb</i> <i>e</i>₂ ∧ <i>e</i>₁ = (<i>ad</i> − <i>bc</i>) <i>e</i>₁ ∧ <i>e</i>₂. C’est la formule <i>u</i>₁<i>v</i>₂ − <i>u</i>₂<i>v</i>₁ appliquée aux deux colonnes.</p></div>
<div class="idea"><p>Produit de la diagonale descendante, moins produit de la diagonale montante. Le signe moins vient de l’antisymétrie : le terme <i>e</i>₂ ∧ <i>e</i>₁ a été retourné.</p></div>
<div class="ex"><p>det ${mat([[3,-2],[1,4]])} = 3 · 4 − (−2) · 1 = 12 + 2 = 14. Et det ${mat([[2,4],[3,6]])} = 12 − 12 = 0 : les colonnes (2 ; 3) et (4 ; 6) sont proportionnelles, le carré unité est écrasé sur une droite.</p></div>
<div class="warn"><p>La faute la plus fréquente est un signe oublié quand <i>b</i> ou <i>c</i> est négatif. Écris le produit montant entre parenthèses avant de le retrancher : 12 − (−2) = 14.</p></div>`},
  {h:'La formule 3 × 3 et la règle de Sarrus',p:`<p>En taille 3, le déterminant est le coefficient de <i>Ae</i>₁ ∧ <i>Ae</i>₂ ∧ <i>Ae</i>₃, c’est-à-dire le produit extérieur des trois colonnes. La formule à six termes du chapitre précédent donne directement le résultat.</p>
<div class="thm"><p>Pour <i>A</i> = ${mat([['<i>a</i>','<i>b</i>','<i>c</i>'],['<i>d</i>','<i>e</i>','<i>f</i>'],['<i>g</i>','<i>h</i>','<i>i</i>']])} :</p><p><b>det <i>A</i> = <i>aei</i> + <i>bfg</i> + <i>cdh</i> − <i>ceg</i> − <i>afh</i> − <i>bdi</i></b>.</p></div>
<div class="why"><p>Les colonnes sont <i>u</i> = (<i>a</i> ; <i>d</i> ; <i>g</i>), <i>v</i> = (<i>b</i> ; <i>e</i> ; <i>h</i>), <i>w</i> = (<i>c</i> ; <i>f</i> ; <i>i</i>). Le coefficient de <i>u</i> ∧ <i>v</i> ∧ <i>w</i> vaut <i>u</i>₁<i>v</i>₂<i>w</i>₃ − <i>u</i>₁<i>v</i>₃<i>w</i>₂ − <i>u</i>₂<i>v</i>₁<i>w</i>₃ + <i>u</i>₂<i>v</i>₃<i>w</i>₁ + <i>u</i>₃<i>v</i>₁<i>w</i>₂ − <i>u</i>₃<i>v</i>₂<i>w</i>₁, soit <i>aei</i> − <i>ahf</i> − <i>dbi</i> + <i>dhc</i> + <i>gbf</i> − <i>gec</i>. Ce sont les six termes annoncés : chacun prend exactement un coefficient par ligne et un par colonne, avec le signe + pour les trois « diagonales descendantes » et − pour les trois « montantes ».</p></div>
<div class="idea"><p>La <b>règle de Sarrus</b> est un moyen mnémotechnique : on recopie les deux premières colonnes à droite de la matrice. Les trois diagonales qui descendent donnent les termes positifs, les trois qui montent les termes négatifs. La figure le montre sur la matrice ${M([[2,1,3],[0,4,1],[5,2,1]])} : 13 − 64 = −51.</p></div>
<div class="warn"><p>Sarrus ne fonctionne <b>qu’en taille 3</b>. En taille 4, le développement compte 24 termes et les diagonales ne les donnent pas. Il faudra alors les cofacteurs du chapitre suivant.</p></div>`,
   fig:sarrusFig},
  {kind:'Méthode',h:'Calculer un déterminant 3 × 3 avec Sarrus',
   p:'<b>Quand :</b> une matrice 3 × 3 à coefficients numériques, sans zéro bien placé qui rendrait un développement plus court. <b>Pourquoi ça marche :</b> les six produits de Sarrus sont exactement les six termes du produit extérieur des colonnes. <b>Comment :</b> 1) recopie mentalement (ou sur l’ardoise) les colonnes 1 et 2 à droite ; 2) calcule séparément les trois produits descendants et additionne-les ; 3) calcule les trois produits montants et additionne-les ; 4) retranche le second total du premier. Écris chaque produit avec ses parenthèses : presque toutes les erreurs viennent des signes.',
   demo:{enonce:`Calcule det <i>A</i> pour <i>A</i> = ${M([[1,2,0],[3,1,2],[2,0,4]])}.`,
    etapes:[{f:'Descendantes : <i>aei</i> + <i>bfg</i> + <i>cdh</i> = 1 · 1 · 4 + 2 · 2 · 2 + 0 · 3 · 0 = 4 + 8 + 0 = 12.',w:'Première diagonale 1, 1, 4 ; deuxième 2, 2, 2 (en repassant par la colonne 1 recopiée) ; troisième 0, 3, 0.'},
     {f:'Montantes : <i>ceg</i> + <i>afh</i> + <i>bdi</i> = 0 · 1 · 2 + 1 · 2 · 0 + 2 · 3 · 4 = 0 + 0 + 24 = 24.',w:'On part du bas : 2, 1, 0 ; puis 0, 2, 1 ; puis 4, 3, 2. Les produits sont les mêmes quel que soit l’ordre des facteurs.'},
     {f:'det <i>A</i> = 12 − 24 = −12.',w:'Descendantes moins montantes.'}],
    conclusion:'<b>det <i>A</i> = −12</b>. Le cube unité est envoyé sur une boîte de volume 12, et l’orientation est renversée.'}},
  {h:'Un déterminant avec Sarrus',p:`Calcule le déterminant de ${mat([[1,3,2],[2,0,1],[4,1,3]])}.`,lab:'det =',ans:-3,
   why:'Descendantes : 1 · 0 · 3 + 3 · 1 · 4 + 2 · 2 · 1 = 0 + 12 + 4 = 16. Montantes : 2 · 0 · 4 + 1 · 1 · 1 + 3 · 2 · 3 = 0 + 1 + 18 = 19. det = 16 − 19 = −3.'},
  {h:'Facteur d’aire et orientation',p:`<p>Le déterminant ne mesure pas seulement ce qui arrive au carré unité : il dit ce qui arrive à <b>toutes</b> les aires.</p>
<div class="thm"><p>Soit <i>A</i> une matrice 2 × 2. Pour tous vecteurs <i>u</i>, <i>v</i> du plan, <b><i>Au</i> ∧ <i>Av</i> = det(<i>A</i>) · <i>u</i> ∧ <i>v</i></b>. Donc <i>A</i> multiplie l’aire de toute figure par |det <i>A</i>|, et conserve l’orientation si det <i>A</i> &gt; 0, la renverse si det <i>A</i> &lt; 0. En taille 3, même énoncé avec les volumes.</p></div>
<div class="why"><p>On écrit <i>u</i> = <i>u</i>₁<i>e</i>₁ + <i>u</i>₂<i>e</i>₂, donc <i>Au</i> = <i>u</i>₁<i>Ae</i>₁ + <i>u</i>₂<i>Ae</i>₂ par linéarité, et de même pour <i>v</i>. Alors <i>Au</i> ∧ <i>Av</i> se développe exactement comme <i>u</i> ∧ <i>v</i>, mais avec <i>Ae</i>₁, <i>Ae</i>₂ à la place de <i>e</i>₁, <i>e</i>₂ : <i>Au</i> ∧ <i>Av</i> = (<i>u</i>₁<i>v</i>₂ − <i>u</i>₂<i>v</i>₁) <i>Ae</i>₁ ∧ <i>Ae</i>₂ = (<i>u</i>₁<i>v</i>₂ − <i>u</i>₂<i>v</i>₁) det(<i>A</i>) <i>e</i>₁ ∧ <i>e</i>₂ = det(<i>A</i>) · <i>u</i> ∧ <i>v</i>. Une figure quelconque s’approche par de petits parallélogrammes, tous multipliés par le même facteur.</p></div>
<div class="ex"><p>Fais défiler les transformations de la figure. Le quart de tour conserve aires et orientation : det = 1. La symétrie d’axe horizontal conserve les aires mais retourne la forme en L : det = −1. Le cisaillement penche la forme sans changer son aire : det = 1. L’homothétie de rapport 1,5 multiplie les aires par 1,5² = 2,25. La projection aplatit tout : det = 0.</p></div>`,
   params:[{id:'k',l:'transformation',min:0,max:5,v:0}],
   draw:v=>forme(PRESETS[v.k].A),
   info:v=>{ const A=PRESETS[v.k].A, d=det2(A); return `${PRESETS[v.k].n} : A = ${M(A)}, det A = <b>${fmt(d)}</b>. Les aires sont multipliées par ${fmt(Math.abs(d))}`+(d<0?', l’orientation est renversée.':d===0?' : tout est écrasé.':', l’orientation est conservée.'); },
   note:'Une matrice de déterminant 1 n’est pas forcément une rotation : le cisaillement et l’étirement-compression gardent les aires sans garder les longueurs.'},
  {h:'Les règles issues de l’alternance',p:`<p>Puisque det <i>A</i> est le produit extérieur des colonnes, toute règle du produit extérieur devient une règle sur les colonnes du déterminant. Voici les quatre qu’on utilise sans cesse.</p>
<div class="prop"><p>1) <b>Échanger deux colonnes</b> change le signe du déterminant.</p><p>2) Si <b>deux colonnes sont égales</b> (ou proportionnelles), det <i>A</i> = 0.</p><p>3) <b>Ajouter à une colonne un multiple d’une autre</b> ne change pas le déterminant.</p><p>4) <b>Multiplier une colonne par λ</b> multiplie le déterminant par λ. En particulier, <b>det(λ<i>A</i>) = λⁿ det <i>A</i></b> pour une matrice <i>n</i> × <i>n</i>.</p></div>
<div class="why"><p>1) vient de l’antisymétrie : échanger deux facteurs d’un produit extérieur change son signe. 2) vient de l’alternance : deux facteurs égaux annulent le produit (et si <i>C</i>ⱼ = λ<i>C</i>ᵢ, on sort λ puis on a deux facteurs égaux). 3) : par linéarité en la colonne <i>j</i>, remplacer <i>C</i>ⱼ par <i>C</i>ⱼ + λ<i>C</i>ᵢ ajoute λ fois un déterminant à deux colonnes égales, c’est-à-dire 0. 4) est la linéarité en une colonne ; pour λ<i>A</i>, les <i>n</i> colonnes sont toutes multipliées par λ, et chacune fait sortir un facteur λ.</p></div>
<div class="ex"><p>det ${mat([[1,2],[3,4]])} = −2, et après échange des colonnes det ${mat([[2,1],[4,3]])} = 6 − 4 = 2. Si on remplace la colonne 2 par <i>C</i>₂ − 2<i>C</i>₁ : det ${mat([[1,0],[3,-2]])} = −2, inchangé. Enfin det(3<i>A</i>) = det ${mat([[3,6],[9,12]])} = 36 − 54 = −18 = 3² · (−2).</p></div>
<div class="warn"><p>det(λ<i>A</i>) n’est pas λ det <i>A</i> : chaque colonne apporte son facteur. Pour une matrice 3 × 3, det(2<i>A</i>) = 8 det <i>A</i>. De même, det(<i>A</i> + <i>B</i>) n’a aucun lien simple avec det <i>A</i> + det <i>B</i>.</p></div>`},
  {kind:'Question',h:'Le déterminant de 3A',p:'Une matrice <i>A</i> de taille 3 × 3 vérifie det <i>A</i> = −2. Que vaut det(3<i>A</i>)&nbsp;?',
   opts:['−6','−18','−54','54'],ans:2,
   why:'Les trois colonnes sont multipliées par 3 et chacune sort un facteur 3 : det(3A) = 3³ · (−2) = −54. La réponse −6 oublie deux des trois colonnes, −18 en oublie une.'},
  {h:'Matrices triangulaires et déterminant d’un produit',p:`<p>Deux résultats rendent beaucoup de déterminants presque gratuits : celui des matrices triangulaires, et la multiplicativité.</p>
<div class="prop"><p>Si <i>A</i> est <b>triangulaire</b> (tous les coefficients au-dessous de la diagonale sont nuls, ou tous ceux au-dessus), alors <b>det <i>A</i> est le produit des coefficients diagonaux</b>. C’est en particulier vrai pour une matrice diagonale.</p></div>
<div class="why"><p>Dans la formule à six termes (ou à <i>n</i>! termes), chaque terme prend un coefficient par ligne et par colonne. Pour une matrice triangulaire supérieure, dès qu’un terme utilise un coefficient au-dessus de la diagonale dans une colonne, il doit compenser en prenant un coefficient au-dessous de la diagonale dans une autre, qui est nul. Seul survit le terme diagonal <i>a</i>₁₁<i>a</i>₂₂…<i>a</i>ₙₙ. Exemple : det ${mat([[2,5,-1],[0,3,4],[0,0,-2]])} = 2 · 3 · (−2) = −12.</p></div>
<div class="thm"><p>Pour deux matrices carrées de même taille, <b>det(<i>AB</i>) = det <i>A</i> · det <i>B</i></b>.</p></div>
<div class="why"><p>Les colonnes de <i>AB</i> sont <i>A</i>(<i>Be</i>₁), …, <i>A</i>(<i>Be</i>ₙ). Par l’étape « facteur d’aire », appliquer <i>A</i> à <i>n</i> vecteurs multiplie leur produit extérieur par det <i>A</i> : <i>ABe</i>₁ ∧ … ∧ <i>ABe</i>ₙ = det(<i>A</i>) · <i>Be</i>₁ ∧ … ∧ <i>Be</i>ₙ = det(<i>A</i>) det(<i>B</i>) <i>e</i>₁ ∧ … ∧ <i>e</i>ₙ. Géométriquement : <i>B</i> multiplie les volumes par det <i>B</i>, puis <i>A</i> par det <i>A</i>.</p></div>
<div class="ex"><p><i>A</i> = ${mat([[2,1],[1,3]])}, det <i>A</i> = 5 ; <i>B</i> = ${mat([[1,2],[0,4]])}, det <i>B</i> = 4. Produit : <i>AB</i> = ${mat([[2,8],[1,14]])}, det <i>AB</i> = 28 − 8 = 20 = 5 · 4. Conséquence : det(<i>A</i>ᵏ) = (det <i>A</i>)ᵏ, et det(<i>AB</i>) = det(<i>BA</i>) même quand <i>AB</i> ≠ <i>BA</i>.</p></div>`},
  {h:'det A ≠ 0 ⇔ A inversible',p:`<div class="blk" data-t="Rappel"><p><i>A</i> est <b>inversible</b> s’il existe <i>B</i> avec <i>AB</i> = <i>BA</i> = I. Une application linéaire de ℝⁿ dans ℝⁿ est bijective si et seulement si l’image de la base canonique, c’est-à-dire la famille des colonnes de sa matrice, est encore une base.</p></div>
<div class="thm"><p>Pour une matrice carrée <i>A</i>, les trois propriétés suivantes sont équivalentes :</p><p>(i) <b>det <i>A</i> ≠ 0</b> ; (ii) les <b>colonnes</b> de <i>A</i> forment une famille <b>libre</b> (donc une base de ℝⁿ) ; (iii) <i>A</i> est <b>inversible</b>.</p><p>Dans ce cas, det(<i>A</i>⁻¹) = 1/det <i>A</i>.</p></div>
<div class="why"><p>(i) ⇔ (ii) est le théorème du chapitre précédent : le produit extérieur des colonnes est nul si et seulement si elles sont liées. (ii) ⇔ (iii) est le rappel : <i>n</i> vecteurs libres de ℝⁿ forment une base, et l’application est alors bijective. Pour la dernière formule, <i>AA</i>⁻¹ = I donne det <i>A</i> · det(<i>A</i>⁻¹) = det I = 1.</p></div>
<div class="idea"><p>Une matrice de déterminant nul écrase l’espace sur quelque chose de plus petit (une droite, un plan) : on ne peut plus revenir en arrière, l’information est perdue. Une matrice de déterminant non nul déforme sans écraser, et on peut défaire la déformation.</p></div>
<div class="ex"><p>${mat([[2,4],[3,6]])} a pour déterminant 0 : ses colonnes sont proportionnelles, elle n’est pas inversible. ${mat([[2,1],[1,3]])} a pour déterminant 5 : elle est inversible et son inverse a pour déterminant 1/5.</p></div>
<div class="warn"><p>Si <i>AB</i> = I avec <i>A</i>, <i>B</i> carrées, alors det <i>A</i> ≠ 0 et <i>A</i> est inversible, d’inverse <i>B</i> : il est inutile de vérifier aussi <i>BA</i> = I. Ce confort n’existe que pour les matrices carrées.</p></div>`},
  {kind:'Méthode',h:'Calculer un déterminant par opérations sur les colonnes',
   p:'<b>Quand :</b> les coefficients sont grands, dépendent d’un paramètre, ou la matrice dépasse la taille 3. <b>Pourquoi ça marche :</b> ajouter à une colonne un multiple d’une autre ne change pas le déterminant, multiplier une colonne par λ le multiplie par λ, et un échange change le signe ; on se ramène à une matrice triangulaire, dont le déterminant est le produit de la diagonale. <b>Comment :</b> 1) choisis un pivot non nul dans la première ligne, de préférence un 1 ; 2) avec <i>C</i>ⱼ ← <i>C</i>ⱼ − λ<i>C</i>pivot, annule les autres coefficients de la première ligne ; 3) recommence sur la deuxième ligne avec les colonnes restantes ; 4) multiplie la diagonale, en tenant compte des facteurs sortis et des échanges. Les mêmes opérations sur les <b>lignes</b> sont permises aussi : on le démontrera au chapitre suivant avec la transposée.',
   demo:{enonce:`Calcule det <i>A</i> pour <i>A</i> = ${M([[1,2,3],[2,3,7],[1,4,5]])}.`,
    etapes:[{f:`<i>C</i>₂ ← <i>C</i>₂ − 2<i>C</i>₁ et <i>C</i>₃ ← <i>C</i>₃ − 3<i>C</i>₁ : det <i>A</i> = det ${M([[1,0,0],[2,-1,1],[1,2,2]])}.`,w:'Le pivot 1 en haut à gauche annule le reste de la première ligne. Le déterminant n’a pas changé.'},
     {f:`<i>C</i>₃ ← <i>C</i>₃ + <i>C</i>₂ : det <i>A</i> = det ${M([[1,0,0],[2,-1,0],[1,2,4]])}.`,w:'Le pivot −1 de la deuxième ligne annule le 1 à sa droite.'},
     {f:'La matrice est triangulaire inférieure : det <i>A</i> = 1 · (−1) · 4 = −4.',w:'Produit des coefficients diagonaux ; aucun facteur n’a été sorti, aucun échange effectué.'},
     {f:'Contrôle par Sarrus : 15 + 14 + 24 − 9 − 28 − 20 = −4.',w:'Descendantes 1·3·5 + 2·7·1 + 3·2·4, montantes 3·3·1 + 1·7·4 + 2·2·5.'}],
    conclusion:'<b>det <i>A</i> = −4</b> ≠ 0 : les trois colonnes forment une base de ℝ³ et <i>A</i> est inversible.'}},
  {h:'Une matrice qui dépend d’un paramètre',p:`Pour quelle valeur de <i>m</i> la matrice ${mat([[1,2,'<i>m</i>'],[0,1,1],[2,3,1]])} n’est-elle <b>pas</b> inversible&nbsp;?`,lab:'m =',ans:1,
   why:'Avec Sarrus : det = 1 · 1 · 1 + 2 · 1 · 2 + m · 0 · 3 − m · 1 · 2 − 1 · 1 · 3 − 2 · 0 · 1 = 1 + 4 − 2m − 3 = 2 − 2m. Il s’annule pour m = 1 : la troisième colonne vaut alors (1 ; 1 ; 1) = (2 ; 1 ; 3) − (1 ; 0 ; 2) = C₂ − C₁, la famille des colonnes est liée.'},
  {kind:'Pratique',h:'Aire 2, orientation renversée',p:`Règle <i>a</i> et <i>b</i> pour que la matrice ${mat([['<i>a</i>',1],[1,'<i>b</i>']])} multiplie les aires par 2 <b>et</b> renverse l’orientation.`,
   params:[{id:'a',l:'a',min:-2,max:2,step:.5,v:2},{id:'b',l:'b',min:-2,max:2,step:.5,v:2}],
   draw:v=>grille2([[v.a,1],[1,v.b]]),
   info:v=>{ const d=v.a*v.b-1; return `det = ${pn(v.a)} · ${pn(v.b)} − 1 · 1 = <b>${fmt(d)}</b>`+(d===0?' : plan aplati':` : aires × ${fmt(Math.abs(d))}, orientation ${d<0?'renversée':'conservée'}`); },
   ok:v=>v.a*v.b-1===-2,
   why:'Il faut det = ab − 1 = −2, c’est-à-dire ab = −1 : par exemple a = 1 et b = −1, ou a = 2 et b = −0,5. Le parallélogramme image a une aire de 2 et il est parcouru dans le sens indirect.'},
  {h:'Combiner les règles',p:'<i>A</i> et <i>B</i> sont deux matrices 3 × 3 avec det <i>A</i> = 4 et det <i>B</i> = −3. Que vaut det(<i>A</i>²<i>B</i>)&nbsp;?',lab:'det =',ans:-48,
   why:'det(A²B) = det A · det A · det B = 4 · 4 · (−3) = −48. La multiplicativité permet de calculer sans connaître les matrices.'},
  {kind:'Récapitulatif',h:'Ce qu’il faut retenir',p:`<div class="keep"><ul>
<li><b>Définition</b> : <i>Ae</i>₁ ∧ … ∧ <i>Ae</i>ₙ = det(<i>A</i>) <i>e</i>₁ ∧ … ∧ <i>e</i>ₙ. Le déterminant est le produit extérieur des colonnes ; det I = 1.</li>
<li><b>2 × 2</b> : <i>ad</i> − <i>bc</i>. <b>3 × 3</b> : règle de Sarrus, <i>aei</i> + <i>bfg</i> + <i>cdh</i> − <i>ceg</i> − <i>afh</i> − <i>bdi</i> (en taille 3 seulement).</li>
<li><b>Sens</b> : |det <i>A</i>| est le facteur par lequel <i>A</i> multiplie les aires (volumes) ; le signe dit si l’orientation est conservée.</li>
<li><b>Règles</b> : échange de deux colonnes → signe opposé ; deux colonnes égales → 0 ; <i>C</i>ⱼ ← <i>C</i>ⱼ + λ<i>C</i>ᵢ → inchangé ; colonne × λ → det × λ ; det(λ<i>A</i>) = λⁿ det <i>A</i>.</li>
<li><b>Triangulaire</b> : produit de la diagonale. <b>Produit</b> : det(<i>AB</i>) = det <i>A</i> · det <i>B</i>, donc det(<i>A</i>ᵏ) = (det <i>A</i>)ᵏ et det(<i>A</i>⁻¹) = 1/det <i>A</i>.</li>
<li><b>Critère</b> : det <i>A</i> ≠ 0 ⇔ colonnes libres ⇔ <i>A</i> inversible.</li>
<li><b>Calcul</b> : opérations sur les colonnes (et sur les lignes) pour se ramener à une matrice triangulaire.</li>
</ul></div>`},
  {kind:'Problème',h:'Une famille de vecteurs à paramètre',
   p:'Dans ℝ³, on considère <i>u</i> = (1 ; 1 ; 1), <i>v</i> = (1 ; 2 ; 4) et <i>w</i> = (1 ; 3 ; <i>m</i>), où <i>m</i> est un réel. On range ces vecteurs en colonnes dans une matrice <i>A</i>. On cherche pour quelle valeur de <i>m</i> la famille (<i>u</i>, <i>v</i>, <i>w</i>) est liée, la relation qui la lie alors, et le volume de la boîte construite sur les trois vecteurs dans les autres cas.',
   parts:[
    {q:'a) Calcule det <i>A</i> pour <i>m</i> = 9.',lab:'det =',ans:2,hint:'Avec Sarrus sur (1 1 1 ; 1 2 3 ; 1 4 9), ou en retranchant la colonne 1 aux deux autres.',why:'C₂ ← C₂ − C₁, C₃ ← C₃ − C₁ donnent (1 0 0 ; 1 1 2 ; 1 3 8), puis C₃ ← C₃ − 2C₂ donne (1 0 0 ; 1 1 0 ; 1 3 2) : det = 1 · 1 · 2 = 2.'},
    {q:'b) Pour quelle valeur de <i>m</i> la famille (<i>u</i>, <i>v</i>, <i>w</i>) est-elle liée&nbsp;?',lab:'m =',ans:7,hint:'Calcule det A en fonction de m (Sarrus donne une expression du premier degré en m) et annule-la.',why:'Sarrus : aei + bfg + cdh = 1·2·m + 1·3·1 + 1·1·4 = 2m + 7 ; ceg + afh + bdi = 1·2·1 + 1·3·4 + 1·1·m = 14 + m. det A = 2m + 7 − 14 − m = m − 7, nul pour m = 7.'},
    {q:'c) Pour <i>m</i> = 7, quelle relation lie les trois vecteurs&nbsp;?',opts:['w = u + v','w = 2u − v','w = −u + 2v','w = 3u − 2v'],ans:2,hint:'Cherche α et β avec w = αu + βv : les deux premières coordonnées donnent α + β = 1 et α + 2β = 3.',why:'α + β = 1 et α + 2β = 3 donnent β = 2, α = −1. Contrôle sur la troisième coordonnée : −1 + 2 · 4 = 7. Donc w = −u + 2v.'},
    {q:'d) Pour <i>m</i> = 5, quel est le volume de la boîte construite sur <i>u</i>, <i>v</i>, <i>w</i>&nbsp;?',lab:'volume =',ans:2,hint:'Le volume est |det A| avec det A = m − 7.',why:'det A = 5 − 7 = −2, donc le volume vaut 2 et la base (u, v, w) est indirecte.'},
    {q:'e) Toujours pour <i>m</i> = 9, que vaut le déterminant de la famille (2<i>u</i>, <i>v</i>, <i>w</i> + 3<i>v</i>)&nbsp;?',lab:'det =',ans:4,hint:'Multiplier une colonne par 2 double le déterminant ; ajouter 3v à w ne change rien.',why:'det(2u, v, w + 3v) = 2 det(u, v, w + 3v) = 2 det(u, v, w) = 2 · 2 = 4.'},
   ],
   sol:'En retranchant la colonne 1 aux deux autres puis 2C₂ à C₃, on obtient pour m = 9 une matrice triangulaire de diagonale 1, 1, 2 : <b>det A = 2</b>.<br>En général, Sarrus donne <b>det A = m − 7</b>. La famille est liée si et seulement si m = 7 ; alors w = (1 ; 3 ; 7) = −u + 2v, ce qu’on vérifie coordonnée par coordonnée.<br>Pour m = 5, det A = −2 : la boîte a un volume de 2 et l’orientation est indirecte.<br>Enfin, les règles de l’alternance donnent det(2u, v, w + 3v) = 2 det(u, v, w) = 4 pour m = 9.'},
  {kind:'Problème',h:'Une matrice antisymétrique n’est jamais inversible',
   p:`Une matrice 3 × 3 est <b>antisymétrique</b> si elle est de la forme <i>A</i> = ${mat([[0,'<i>a</i>','<i>b</i>'],['−<i>a</i>',0,'<i>c</i>'],['−<i>b</i>','−<i>c</i>',0]])} : des zéros sur la diagonale, et des coefficients opposés de part et d’autre. On veut montrer qu’une telle matrice n’est jamais inversible, trouver un vecteur non nul qu’elle envoie sur 0, puis calculer det(<i>A</i> + I). On prendra <i>a</i> = 1, <i>b</i> = 2, <i>c</i> = 3 pour les calculs numériques.`,
   parts:[
    {q:'a) Calcule det <i>A</i> pour <i>a</i> = 1, <i>b</i> = 2, <i>c</i> = 3.',lab:'det =',ans:0,hint:'Sarrus : la plupart des six produits contiennent un 0 de la diagonale.',why:'Les termes aei, ceg, afh, bdi contiennent un coefficient diagonal nul. Il reste bfg + cdh = 1 · 3 · (−2) + 2 · (−1) · (−3) = −6 + 6 = 0.'},
    {q:'b) Pourquoi det <i>A</i> = 0 pour toutes les valeurs de <i>a</i>, <i>b</i>, <i>c</i>&nbsp;?',opts:['Parce que la diagonale est nulle, et le déterminant est le produit de la diagonale.','Parce que les deux seuls termes non nuls de Sarrus, a · c · (−b) et b · (−a) · (−c), sont opposés.','Parce qu’une colonne est nulle.','Parce que la matrice est égale à son opposée.'],ans:1,hint:'Écris les six termes de Sarrus avec des lettres. Lesquels survivent ?',why:'Dans Sarrus, quatre termes contiennent un coefficient diagonal, donc 0. Les deux autres sont bfg = a · c · (−b) = −abc et cdh = b · (−a) · (−c) = abc : leur somme est nulle. Le produit de la diagonale ne donne le déterminant que pour une matrice triangulaire, ce qui n’est pas le cas ici.'},
    {q:'c) Comme det <i>A</i> = 0, les colonnes sont liées et il existe <i>x</i> ≠ 0 avec <i>Ax</i> = 0. Pour <i>a</i> = 1, <i>b</i> = 2, <i>c</i> = 3, lequel de ces vecteurs convient&nbsp;?',opts:['(1 ; 2 ; 3)','(3 ; −2 ; 1)','(1 ; −2 ; 3)','(2 ; 3 ; 1)'],ans:1,hint:'Calcule Ax ligne par ligne : la première ligne (0 1 2) fois x doit donner 0.',why:'Pour x = (3 ; −2 ; 1) : ligne 1 : 0 · 3 + 1 · (−2) + 2 · 1 = 0 ; ligne 2 : −3 + 0 + 3 = 0 ; ligne 3 : −6 + 6 + 0 = 0. En général x = (c ; −b ; a) convient.'},
    {q:'d) Toujours pour <i>a</i> = 1, <i>b</i> = 2, <i>c</i> = 3, calcule det(<i>A</i> + I).',lab:'det =',ans:15,hint:'A + I = (1 1 2 ; −1 1 3 ; −2 −3 1). Sarrus, ou opérations sur les colonnes.',why:'Descendantes : 1 · 1 · 1 + 1 · 3 · (−2) + 2 · (−1) · (−3) = 1 − 6 + 6 = 1. Montantes : 2 · 1 · (−2) + 1 · 3 · (−3) + 1 · (−1) · 1 = −4 − 9 − 1 = −14. det = 1 + 14 = 15. On peut montrer qu’en général det(A + I) = 1 + a² + b² + c².'},
   ],
   sol:'Par Sarrus, les quatre termes qui touchent la diagonale sont nuls et les deux autres valent −abc et +abc : <b>det A = 0</b> quels que soient a, b, c. Une matrice antisymétrique 3 × 3 n’est donc jamais inversible.<br>Ses colonnes sont liées : il existe x ≠ 0 avec Ax = 0. On vérifie que <b>x = (c ; −b ; a)</b> convient : ligne 1 : a · (−b) + b · a = 0, ligne 2 : −a · c + c · a = 0, ligne 3 : −b · c − c · (−b) = 0. Pour a = 1, b = 2, c = 3 : x = (3 ; −2 ; 1).<br>Enfin det(A + I) = 15 pour ces valeurs ; en général <b>det(A + I) = 1 + a² + b² + c²</b>, toujours strictement positif : A + I est toujours inversible, alors que A ne l’est jamais.'},
]},

/* ===================== 3. MINEURS, COFACTEURS ET INVERSE ===================== */
{subj:'gred',sem:'lin',id:'gred-cofacteurs',h:'Mineurs, cofacteurs et inverse',p:'Mineurs et cofacteurs, le développement d’un déterminant selon une ligne ou une colonne, la comatrice et la formule A · ᵗcom(A) = det(A) I, l’inverse d’une matrice régulière, la comparaison avec Gauss-Jordan, et det ᵗA = det A : tout ce qui vaut pour les colonnes vaut pour les lignes.',steps:[
  {h:'Mineurs et cofacteurs',p:`<p>Pour calculer un déterminant 4 × 4, Sarrus ne sert plus. L’idée est de le <b>ramener à des déterminants plus petits</b>. Les briques de cette réduction sont les mineurs et les cofacteurs.</p>
<div class="def"><p>Soit <i>A</i> une matrice carrée de taille <i>n</i>. Le <b>mineur</b> <i>M</i>ᵢⱼ est le déterminant de la matrice (<i>n</i> − 1) × (<i>n</i> − 1) obtenue en <b>barrant la ligne <i>i</i> et la colonne <i>j</i></b> de <i>A</i>. Le <b>cofacteur</b> est le mineur muni d’un signe :</p><p><b><i>C</i>ᵢⱼ = (−1)ⁱ⁺ʲ <i>M</i>ᵢⱼ</b>.</p><p>Les signes (−1)ⁱ⁺ʲ forment un damier qui commence par + en haut à gauche : ${damier}.</p></div>
<div class="idea"><p>Barrer la ligne <i>i</i> et la colonne <i>j</i>, c’est ne garder que ce qui ne « voit » pas le coefficient <i>a</i>ᵢⱼ. Le cofacteur mesure la contribution de <i>a</i>ᵢⱼ au déterminant : on verra à l’étape suivante que det <i>A</i> est une somme de produits <i>a</i>ᵢⱼ<i>C</i>ᵢⱼ. Sur la figure, choisis une ligne et une colonne : les quatre cases qui restent forment le mineur, et le signe du damier donne le cofacteur.</p></div>
<div class="ex"><p>Pour <i>A</i> = ${M(AMIN)}, le mineur <i>M</i>₁₂ s’obtient en barrant la ligne 1 et la colonne 2 : il reste ${mat([[0,1],[5,-2]])}, de déterminant 0 · (−2) − 1 · 5 = −5. Le signe en position (1, 2) est −, donc <i>C</i>₁₂ = −(−5) = 5. De même <i>M</i>₁₁ = det ${mat([[4,1],[2,-2]])} = −8 − 2 = −10, de signe +, donc <i>C</i>₁₁ = −10.</p></div>`,
   params:[{id:'i',l:'ligne barrée i',min:1,max:3,v:1},{id:'j',l:'colonne barrée j',min:1,max:3,v:2}],
   draw:v=>mineurFig(AMIN,v.i-1,v.j-1),
   info:v=>{ const i=v.i-1,j=v.j-1, R=AMIN.filter((_,r)=>r!==i).map(r=>r.filter((_,c)=>c!==j)); return `M<sub>${v.i}${v.j}</sub> = det ${M(R)} = ${fmt(R[0][0])} · ${pn(R[1][1])} − ${fmt(R[0][1])} · ${pn(R[1][0])} = <b>${fmt(minor(AMIN,i,j))}</b>, &nbsp; C<sub>${v.i}${v.j}</sub> = (−1)<sup>${v.i}+${v.j}</sup> · ${pn(minor(AMIN,i,j))} = <b>${fmt(cof(AMIN,i,j))}</b>`; },
   note:'Le damier des signes ne dépend que de la position (i, j), pas des coefficients. Deux cases voisines ont toujours des signes opposés.'},
  {h:'Développer selon une ligne ou une colonne',p:`<p>Voici le théorème qui ramène un déterminant <i>n</i> × <i>n</i> à <i>n</i> déterminants (<i>n</i> − 1) × (<i>n</i> − 1).</p>
<div class="thm"><p><b>Développement selon la ligne <i>i</i></b> : det <i>A</i> = <i>a</i>ᵢ₁<i>C</i>ᵢ₁ + <i>a</i>ᵢ₂<i>C</i>ᵢ₂ + … + <i>a</i>ᵢₙ<i>C</i>ᵢₙ.</p><p><b>Développement selon la colonne <i>j</i></b> : det <i>A</i> = <i>a</i>₁ⱼ<i>C</i>₁ⱼ + <i>a</i>₂ⱼ<i>C</i>₂ⱼ + … + <i>a</i>ₙⱼ<i>C</i>ₙⱼ.</p><p>Le résultat est le même quelle que soit la ligne ou la colonne choisie.</p></div>
<div class="why"><p><b>Idée, pour la colonne 1 en taille 3.</b> La première colonne est <i>Ae</i>₁ = <i>a</i>₁₁<i>e</i>₁ + <i>a</i>₂₁<i>e</i>₂ + <i>a</i>₃₁<i>e</i>₃. Par linéarité en cette colonne, <i>Ae</i>₁ ∧ <i>Ae</i>₂ ∧ <i>Ae</i>₃ se coupe en trois morceaux : <i>a</i>₁₁ <i>e</i>₁ ∧ <i>Ae</i>₂ ∧ <i>Ae</i>₃ + <i>a</i>₂₁ <i>e</i>₂ ∧ <i>Ae</i>₂ ∧ <i>Ae</i>₃ + <i>a</i>₃₁ <i>e</i>₃ ∧ <i>Ae</i>₂ ∧ <i>Ae</i>₃. Dans le premier, la présence de <i>e</i>₁ tue toutes les composantes en <i>e</i>₁ de <i>Ae</i>₂ et <i>Ae</i>₃ : il reste le déterminant 2 × 2 des lignes 2 et 3 des colonnes 2 et 3, c’est-à-dire <i>M</i>₁₁. Dans le deuxième, <i>e</i>₂ est en tête : pour le ramener à l’ordre <i>e</i>₁, <i>e</i>₂, <i>e</i>₃ il faut un échange, d’où le signe − : on obtient −<i>M</i>₂₁. Dans le troisième, deux échanges : +<i>M</i>₃₁. Les signes sont exactement ceux du damier.</p><p><b>Vérification sur Sarrus.</b> En regroupant les six termes selon <i>a</i>, <i>b</i>, <i>c</i> (première ligne) : <i>a</i>(<i>ei</i> − <i>fh</i>) − <i>b</i>(<i>di</i> − <i>fg</i>) + <i>c</i>(<i>dh</i> − <i>eg</i>), ce qui est bien <i>aC</i>₁₁ + <i>bC</i>₁₂ + <i>cC</i>₁₃.</p></div>
<div class="ex"><p>det ${mat([[1,2,3],[0,4,5],[1,0,6]])} selon la colonne 1 : 1 · <i>C</i>₁₁ + 0 · <i>C</i>₂₁ + 1 · <i>C</i>₃₁ = 1 · (24 − 0) + 0 + 1 · (10 − 12) = 24 − 2 = 22. Selon la ligne 1 : 1 · 24 − 2 · (0 − 5) + 3 · (0 − 4) = 24 + 10 − 12 = 22. Même résultat.</p></div>`,
   note:'Pour une matrice 4 × 4, on développe en quatre déterminants 3 × 3, chacun calculable par Sarrus. C’est la première méthode valable en toute taille.'},
  {kind:'Méthode',h:'Développer selon la ligne ou la colonne la plus creuse',
   p:'<b>Quand :</b> une matrice qui contient des zéros, ou une matrice 4 × 4 et plus, ou un déterminant à paramètre dont on veut une expression factorisée. <b>Pourquoi ça marche :</b> le développement vaut selon n’importe quelle ligne ou colonne, et chaque zéro supprime un cofacteur à calculer. <b>Comment :</b> 1) repère la ligne ou la colonne qui contient le <b>plus de zéros</b> ; 2) pour chaque coefficient <i>a</i>ᵢⱼ non nul de cette ligne, barre sa ligne et sa colonne, calcule le mineur <i>M</i>ᵢⱼ, puis affecte le signe (−1)ⁱ⁺ʲ du damier ; 3) additionne les produits <i>a</i>ᵢⱼ<i>C</i>ᵢⱼ. Si aucune ligne n’est creuse, crée d’abord des zéros avec les opérations sur les colonnes (ou les lignes) du chapitre précédent.',
   demo:{enonce:`Calcule det <i>A</i> pour <i>A</i> = ${M([[3,0,2],[1,5,0],[4,0,-1]])}.`,
    etapes:[{f:'La colonne 2 contient deux zéros : on développe selon elle. Seul <i>a</i>₂₂ = 5 compte.',w:'Un seul mineur à calculer au lieu de trois.'},
     {f:'Signe en position (2, 2) : (−1)²⁺² = +.',w:'Centre du damier : +.'},
     {f:`En barrant la ligne 2 et la colonne 2, il reste ${mat([[3,2],[4,-1]])}, de déterminant 3 · (−1) − 2 · 4 = −3 − 8 = −11.`,w:'C’est le mineur M₂₂, donc C₂₂ = −11.'},
     {f:'det <i>A</i> = 5 · (−11) = −55.',w:'Coefficient × cofacteur. Les deux autres termes sont nuls.'},
     {f:'Contrôle par Sarrus : 3·5·(−1) + 0 + 2·1·0 − 2·5·4 − 0 − 0 = −15 − 40 = −55.',w:'Les deux méthodes s’accordent.'}],
    conclusion:'<b>det <i>A</i> = −55</b>, obtenu avec un seul déterminant 2 × 2.'}},
  {h:'Une ligne presque vide',p:`Calcule le déterminant de ${mat([[0,2,0],[3,1,4],[1,5,2]])} en développant selon la ligne 1.`,lab:'det =',ans:-4,
   why:'Seul a₁₂ = 2 est non nul sur la ligne 1. Signe (−1)¹⁺² = −. Mineur : det(3 4 ; 1 2) = 6 − 4 = 2. det = 2 · (−2) = −4.'},
  {h:'La comatrice et la formule A · ᵗcom(A) = det(A) I',p:`<p>Rangeons tous les cofacteurs dans une matrice. Elle a une propriété remarquable qui mène droit à l’inverse.</p>
<div class="def"><p>La <b>comatrice</b> de <i>A</i>, notée com(<i>A</i>), est la matrice des cofacteurs : son coefficient (<i>i</i>, <i>j</i>) est <i>C</i>ᵢⱼ. Sa <b>transposée</b> ᵗcom(<i>A</i>) a pour coefficient (<i>i</i>, <i>j</i>) le cofacteur <i>C</i>ⱼᵢ.</p></div>
<div class="thm"><p><b><i>A</i> · ᵗcom(<i>A</i>) = det(<i>A</i>) · I</b>.</p></div>
<div class="why"><p>Le coefficient (<i>i</i>, <i>k</i>) du produit est « ligne <i>i</i> de <i>A</i> fois colonne <i>k</i> de ᵗcom(<i>A</i>) », c’est-à-dire ligne <i>i</i> de <i>A</i> fois <b>ligne <i>k</i> de com(<i>A</i>)</b> : <i>a</i>ᵢ₁<i>C</i>ₖ₁ + <i>a</i>ᵢ₂<i>C</i>ₖ₂ + … + <i>a</i>ᵢₙ<i>C</i>ₖₙ.</p><p>• Sur la <b>diagonale</b> (<i>k</i> = <i>i</i>), c’est le développement de det <i>A</i> selon la ligne <i>i</i> : on trouve det <i>A</i>.</p><p>• <b>Hors diagonale</b> (<i>k</i> ≠ <i>i</i>), c’est le développement selon la ligne <i>k</i> d’une matrice <i>A</i>′ obtenue en remplaçant la ligne <i>k</i> de <i>A</i> par sa ligne <i>i</i> (les cofacteurs de la ligne <i>k</i> ne dépendent pas de la ligne <i>k</i> elle-même). Or <i>A</i>′ a <b>deux lignes égales</b>, donc det <i>A</i>′ = 0.</p></div>
<div class="ex"><p>Pour <i>A</i> = ${mat([['<i>a</i>','<i>b</i>'],['<i>c</i>','<i>d</i>']])} : <i>C</i>₁₁ = <i>d</i>, <i>C</i>₁₂ = −<i>c</i>, <i>C</i>₂₁ = −<i>b</i>, <i>C</i>₂₂ = <i>a</i>. Donc com(<i>A</i>) = ${mat([['<i>d</i>','−<i>c</i>'],['−<i>b</i>','<i>a</i>']])} et ᵗcom(<i>A</i>) = ${mat([['<i>d</i>','−<i>b</i>'],['−<i>c</i>','<i>a</i>']])}. Produit : ${mat([['<i>ad</i> − <i>bc</i>','−<i>ab</i> + <i>ba</i>'],['<i>cd</i> − <i>dc</i>','−<i>cb</i> + <i>ad</i>']])} = (<i>ad</i> − <i>bc</i>) I.</p></div>`,
   note:'On a utilisé qu’un déterminant à deux lignes égales est nul. C’est la version « lignes » d’une règle vue pour les colonnes ; la dernière étape du chapitre justifie ce passage.'},
  {h:'L’inverse d’une matrice régulière',p:`<p>La formule <i>A</i> · ᵗcom(<i>A</i>) = det(<i>A</i>) I dit presque que ᵗcom(<i>A</i>) est l’inverse de <i>A</i> : il ne manque qu’une division par det <i>A</i>, possible dès qu’il est non nul.</p>
<div class="def"><p>Une matrice carrée est dite <b>régulière</b> si det <i>A</i> ≠ 0, <b>singulière</b> sinon. Régulière veut donc dire inversible.</p></div>
<div class="thm"><p>Si <i>A</i> est régulière, alors</p><p><b><i>A</i>⁻¹ = ${F(1,'det <i>A</i>')} ᵗcom(<i>A</i>)</b>,</p><p>c’est-à-dire : le coefficient (<i>i</i>, <i>j</i>) de <i>A</i>⁻¹ est <i>C</i>ⱼᵢ/det <i>A</i>.</p></div>
<div class="why"><p>En divisant <i>A</i> · ᵗcom(<i>A</i>) = det(<i>A</i>) I par le réel non nul det <i>A</i>, on obtient <i>A</i> · <i>B</i> = I avec <i>B</i> = ᵗcom(<i>A</i>)/det <i>A</i>. Pour une matrice carrée, <i>AB</i> = I suffit à garantir que <i>B</i> est l’inverse de <i>A</i> (chapitre précédent).</p></div>
<div class="ex"><p>En taille 2, on retrouve la formule connue : ${mat([['<i>a</i>','<i>b</i>'],['<i>c</i>','<i>d</i>']])}⁻¹ = ${F(1,'<i>ad</i> − <i>bc</i>')} ${mat([['<i>d</i>','−<i>b</i>'],['−<i>c</i>','<i>a</i>']])}. Pour <i>A</i> = ${mat([[4,3],[2,2]])} : det <i>A</i> = 8 − 6 = 2, et <i>A</i>⁻¹ = ½ ${mat([[2,-3],[-2,4]])} = ${M([[1,-1.5],[-1,2]])}. Contrôle : 4 · 1 + 3 · (−1) = 1, 4 · (−1,5) + 3 · 2 = 0.</p></div>
<div class="warn"><p>N’oublie pas la <b>transposée</b> : c’est <i>C</i>ⱼᵢ, et non <i>C</i>ᵢⱼ, qui occupe la place (<i>i</i>, <i>j</i>) de l’inverse. En taille 2, on le voit à ce que <i>b</i> et <i>c</i> changent de signe mais restent à leur place.</p></div>`},
  {kind:'Méthode',h:'Inverser une matrice 3 × 3 par la comatrice',
   p:'<b>Quand :</b> pour inverser une petite matrice, surtout si elle contient des paramètres ou si on ne veut qu’un seul coefficient de l’inverse. <b>Pourquoi ça marche :</b> <i>A</i> · ᵗcom(<i>A</i>) = det(<i>A</i>) I. <b>Comment :</b> 1) calcule det <i>A</i> ; s’il est nul, il n’y a pas d’inverse, arrête-toi ; 2) calcule les 9 cofacteurs, ligne par ligne, avec le damier + − + / − + − / + − + ; 3) range-les dans com(<i>A</i>) puis <b>transpose</b> ; 4) divise par det <i>A</i> ; 5) contrôle une ligne de <i>A</i> fois les colonnes de <i>A</i>⁻¹ : tu dois retrouver une ligne de I.',
   demo:{enonce:`Inverse <i>A</i> = ${M([[2,1,0],[1,1,0],[3,1,1]])}.`,
    etapes:[{f:'det <i>A</i> selon la colonne 3 : seul <i>a</i>₃₃ = 1 est non nul, signe +, mineur det(2 1 ; 1 1) = 2 − 1 = 1. Donc det <i>A</i> = 1.',w:'La colonne 3 est la plus creuse. A est régulière.'},
     {f:'Ligne 1 des cofacteurs : <i>C</i>₁₁ = +(1 · 1 − 0 · 1) = 1, <i>C</i>₁₂ = −(1 · 1 − 0 · 3) = −1, <i>C</i>₁₃ = +(1 · 1 − 1 · 3) = −2.',w:'Pour chaque position, on barre sa ligne et sa colonne, puis on applique le signe + − +.'},
     {f:'Ligne 2 : <i>C</i>₂₁ = −(1 · 1 − 0 · 1) = −1, <i>C</i>₂₂ = +(2 · 1 − 0 · 3) = 2, <i>C</i>₂₃ = −(2 · 1 − 1 · 3) = 1.',w:'Signes − + −.'},
     {f:'Ligne 3 : <i>C</i>₃₁ = +(1 · 0 − 0 · 1) = 0, <i>C</i>₃₂ = −(2 · 0 − 0 · 1) = 0, <i>C</i>₃₃ = +(2 · 1 − 1 · 1) = 1.',w:'Signes + − +.'},
     {f:`com(<i>A</i>) = ${M([[1,-1,-2],[-1,2,1],[0,0,1]])}, donc <i>A</i>⁻¹ = ${F(1,1)} ᵗcom(<i>A</i>) = ${M([[1,-1,0],[-1,2,0],[-2,1,1]])}.`,w:'On transpose : les lignes de com(A) deviennent les colonnes. Division par det A = 1.'},
     {f:'Contrôle : ligne 3 de <i>A</i>, (3 1 1), fois les colonnes de <i>A</i>⁻¹ : 3 − 1 − 2 = 0, −3 + 2 + 1 = 0, 0 + 0 + 1 = 1.',w:'On retrouve (0 0 1), la ligne 3 de I.'}],
    conclusion:`<b><i>A</i>⁻¹ = ${M([[1,-1,0],[-1,2,0],[-2,1,1]])}</b>. Remarque : sans la transposition, on aurait écrit com(<i>A</i>) à la place, et le contrôle aurait échoué : 3 · 1 + 1 · (−1) + 1 · 0 = 2 ≠ 0.`}},
  {h:'L’inverse d’une matrice 2 × 2',p:`Quel est l’inverse de ${mat([[5,3],[3,2]])}&nbsp;?`,
   opts:[mat([[2,-3],[-3,5]]),mat([[5,-3],[-3,2]]),mat([[2,3],[3,5]]),mat([[-2,3],[3,-5]])],ans:0,
   why:'det = 10 − 9 = 1. Comatrice (2 −3 ; −3 5), transposée identique ici car la matrice est symétrique, divisée par 1. Contrôle : 5 · 2 + 3 · (−3) = 1 et 5 · (−3) + 3 · 5 = 0.'},
  {h:'Un coefficient de l’inverse',p:`Soit <i>A</i> = ${mat([[1,2,0],[0,1,1],[1,0,2]])}. Calcule le coefficient (ligne 2, colonne 3) de <i>A</i>⁻¹, en valeur décimale.`,lab:'(A⁻¹)₂₃ =',ans:-0.25,tol:.001,
   why:'det A selon la ligne 1 : 1 · (2 − 0) − 2 · (0 − 1) + 0 = 4. Le coefficient (2, 3) de A⁻¹ est C₃₂/det A, à cause de la transposée. C₃₂ = −det(1 0 ; 0 1) = −1. Donc −1/4 = −0,25. Attention : C₂₃ = −det(1 2 ; 1 0) = 2 aurait donné 0,5, faux.'},
  {kind:'Méthode',h:'Choisir entre comatrice et Gauss-Jordan',
   p:'<div class="blk" data-t="Rappel"><p>La méthode de <b>Gauss-Jordan</b> inverse <i>A</i> en écrivant la matrice augmentée [<i>A</i> | I] et en appliquant des opérations sur les lignes (échange, <i>L</i>ᵢ ← λ<i>L</i>ᵢ, <i>L</i>ᵢ ← <i>L</i>ᵢ + λ<i>L</i>ⱼ) jusqu’à obtenir [I | <i>B</i>] ; alors <i>B</i> = <i>A</i>⁻¹. Si on tombe sur une ligne nulle à gauche, <i>A</i> n’est pas inversible.</p></div><b>Quand choisir quoi :</b> la <b>comatrice</b> donne une <b>formule</b> : idéale en taille 2, pour une matrice à paramètre, ou quand un seul coefficient de l’inverse est demandé. <b>Gauss-Jordan</b> demande moins de calculs dès la taille 3 et beaucoup moins en taille 4 et au-delà (la comatrice exige <i>n</i>² déterminants de taille <i>n</i> − 1), et il détecte au passage une matrice singulière. <b>Comment :</b> 1) taille 2 ou coefficient isolé : comatrice ; 2) taille 3 numérique : au choix, mais contrôle toujours avec <i>AA</i>⁻¹ = I ; 3) taille 4 et plus, ou matrice pleine : Gauss-Jordan.',
   demo:{enonce:`Inverse <i>A</i> = ${M([[1,2],[3,7]])} par les deux méthodes et compare.`,
    etapes:[{f:'Comatrice : det <i>A</i> = 7 − 6 = 1, com(<i>A</i>) = (7 −3 ; −2 1), ᵗcom(<i>A</i>) = (7 −2 ; −3 1). Donc <i>A</i>⁻¹ = (7 −2 ; −3 1).',w:'Formule directe : on échange a et d, on change le signe de b et c, on divise par 1.'},
     {f:'Gauss-Jordan : [1 2 | 1 0 ; 3 7 | 0 1]. <i>L</i>₂ ← <i>L</i>₂ − 3<i>L</i>₁ : [1 2 | 1 0 ; 0 1 | −3 1].',w:'On annule le 3 sous le pivot 1.'},
     {f:'<i>L</i>₁ ← <i>L</i>₁ − 2<i>L</i>₂ : [1 0 | 7 −2 ; 0 1 | −3 1].',w:'On annule le 2 au-dessus du pivot 1 de la deuxième ligne. À gauche, c’est I.'},
     {f:'Les deux méthodes donnent <i>A</i>⁻¹ = (7 −2 ; −3 1). Contrôle : 1 · 7 + 2 · (−3) = 1, 3 · 7 + 7 · (−3) = 0.',w:'Même résultat, comme il se doit : l’inverse est unique.'}],
    conclusion:'En taille 2, la comatrice est plus rapide : deux opérations. En taille 3, les deux méthodes se valent ; au-delà, Gauss-Jordan l’emporte nettement.'}},
  {h:'Le déterminant de la transposée',p:`<p>Depuis le début, le déterminant est défini à partir des <b>colonnes</b>. Pourtant on a développé selon des lignes et utilisé des déterminants à deux lignes égales. Le théorème suivant justifie tout cela d’un coup.</p>
<div class="def"><p>La <b>transposée</b> ᵗ<i>A</i> de <i>A</i> est la matrice dont les lignes sont les colonnes de <i>A</i> : son coefficient (<i>i</i>, <i>j</i>) est <i>a</i>ⱼᵢ.</p></div>
<div class="thm"><p><b>det ᵗ<i>A</i> = det <i>A</i></b>.</p></div>
<div class="why"><p><b>Idée.</b> Chaque terme du déterminant est un produit de <i>n</i> coefficients pris un par ligne et un par colonne, affecté d’un signe qui compte les échanges nécessaires pour remettre les colonnes dans l’ordre. Transposer échange le rôle des lignes et des colonnes : les mêmes produits apparaissent, et remettre les lignes dans l’ordre demande exactement le même nombre d’échanges (on défait la même permutation à l’envers). En taille 3, on le voit sur Sarrus : les six produits de ᵗ<i>A</i> sont ceux de <i>A</i>, avec les mêmes signes.</p></div>
<div class="prop"><p><b>Conséquence</b> : tout ce qui a été démontré pour les colonnes vaut pour les lignes. Échanger deux lignes change le signe ; deux lignes égales donnent 0 ; <i>L</i>ᵢ ← <i>L</i>ᵢ + λ<i>L</i>ⱼ ne change rien ; on peut développer selon une ligne ; et les lignes de <i>A</i> sont libres si et seulement si ses colonnes le sont.</p></div>
<div class="ex"><p><i>A</i> = ${mat([[1,2,0],[3,1,4],[0,2,1]])} : selon la ligne 1, det <i>A</i> = 1 · (1 − 8) − 2 · (3 − 0) + 0 = −13. Sa transposée ᵗ<i>A</i> = ${mat([[1,3,0],[2,1,2],[0,4,1]])} : selon la ligne 1, 1 · (1 − 8) − 3 · (2 − 0) + 0 = −13. Égalité.</p></div>`,
   note:'Pour une matrice symétrique (ᵗA = A), le théorème ne dit rien de neuf. Son intérêt est de libérer les calculs : on choisit à chaque étape l’opération la plus commode, sur une ligne ou sur une colonne.'},
  {kind:'Pratique',h:'Aplatis la boîte',p:'Les colonnes <i>u</i> = (2 ; 1 ; 0), <i>v</i> = (0 ; 1 ; 1) et <i>w</i> = (1 ; 0 ; <i>t</i>) forment une matrice <i>A</i>. Règle <i>t</i> pour que <i>A</i> soit <b>singulière</b> : la boîte doit s’aplatir.',
   params:[{id:'t',l:'t',min:-2,max:2,step:.5,v:1},{id:'az',l:'vue (rotation)',min:0,max:90,step:15,v:30,u:'°'}],
   draw:v=>boite([2,1,0],[0,1,1],[1,0,v.t],v.az,3.4),
   info:v=>`det A = <b>${fmt(2*v.t+1)}</b>`+(2*v.t+1===0?' : singulière, les trois vecteurs sont coplanaires':''),
   ok:v=>2*v.t+1===0,
   why:'Selon la ligne 1 de A = (2 0 1 ; 1 1 0 ; 0 1 t) : 2 · (t − 0) − 0 + 1 · (1 − 0) = 2t + 1. Nul pour t = −0,5 : alors w = ½ u − ½ v, les trois vecteurs sont dans un même plan.'},
  {kind:'Question',h:'Lignes ou colonnes ?',p:'Laquelle de ces affirmations est <b>fausse</b>&nbsp;?',
   opts:['Si deux lignes de A sont proportionnelles, det A = 0.','Remplacer L₂ par L₂ + 5L₁ ne change pas det A.','Remplacer L₂ par 5L₂ ne change pas det A.','Les lignes de A sont libres si et seulement si ses colonnes le sont.'],ans:2,
   why:'Multiplier une ligne par 5 multiplie le déterminant par 5 (linéarité en cette ligne, via det ᵗA = det A). Les trois autres affirmations sont des conséquences directes du théorème det ᵗA = det A.'},
  {kind:'Récapitulatif',h:'Ce qu’il faut retenir',p:`<div class="keep"><ul>
<li><b>Mineur</b> <i>M</i>ᵢⱼ : déterminant obtenu en barrant la ligne <i>i</i> et la colonne <i>j</i>. <b>Cofacteur</b> <i>C</i>ᵢⱼ = (−1)ⁱ⁺ʲ <i>M</i>ᵢⱼ, signes en damier à partir de + en haut à gauche.</li>
<li><b>Développement</b> selon la ligne <i>i</i> : det <i>A</i> = Σⱼ <i>a</i>ᵢⱼ<i>C</i>ᵢⱼ ; selon la colonne <i>j</i> : Σᵢ <i>a</i>ᵢⱼ<i>C</i>ᵢⱼ. Choisis la ligne ou la colonne la plus creuse.</li>
<li><b>Comatrice</b> com(<i>A</i>) = (<i>C</i>ᵢⱼ) et <b><i>A</i> · ᵗcom(<i>A</i>) = det(<i>A</i>) I</b> : diagonale = développement, hors diagonale = déterminant à deux lignes égales = 0.</li>
<li><b>Inverse</b> d’une matrice régulière (det ≠ 0) : <i>A</i>⁻¹ = ᵗcom(<i>A</i>)/det <i>A</i>, coefficient (<i>i</i>, <i>j</i>) égal à <i>C</i>ⱼᵢ/det <i>A</i>. En taille 2 : échanger <i>a</i> et <i>d</i>, changer le signe de <i>b</i> et <i>c</i>, diviser par <i>ad</i> − <i>bc</i>.</li>
<li><b>Gauss-Jordan</b> ([<i>A</i> | I] → [I | <i>A</i>⁻¹]) est préférable dès la taille 4 ; la comatrice sert pour la taille 2, les paramètres et un coefficient isolé.</li>
<li><b>det ᵗ<i>A</i> = det <i>A</i></b> : toutes les règles des colonnes valent pour les lignes.</li>
</ul></div>`},
  {kind:'Problème',h:'L’inverse d’une matrice à paramètre',
   p:`Pour un réel <i>m</i>, on pose <i>A</i> = ${mat([['<i>m</i>',1,0],[1,'<i>m</i>',1],[0,1,'<i>m</i>']])}. On veut savoir pour quelles valeurs de <i>m</i> la matrice est régulière, puis calculer son inverse pour <i>m</i> = 2 par la comatrice. Un développement bien choisi donne det <i>A</i> sous une forme factorisée.`,
   parts:[
    {q:'a) Calcule det <i>A</i> pour <i>m</i> = 2.',lab:'det =',ans:4,hint:'Développe selon la ligne 1 : 2 · C₁₁ + 1 · C₁₂.',why:'C₁₁ = det(2 1 ; 1 2) = 3, C₁₂ = −det(1 1 ; 0 2) = −2. det A = 2 · 3 + 1 · (−2) = 4.'},
    {q:'b) En général, det <i>A</i> = <i>m</i>³ − 2<i>m</i> = <i>m</i>(<i>m</i>² − 2). Combien de valeurs de <i>m</i> rendent <i>A</i> singulière&nbsp;?',lab:'nombre de valeurs :',ans:3,hint:'Résous m(m² − 2) = 0.',why:'m = 0, m = √2 ou m = −√2 : trois valeurs. Pour toute autre valeur, A est régulière.'},
    {q:'c) Pour <i>m</i> = 2, quel est le coefficient (1, 1) de <i>A</i>⁻¹&nbsp;? Réponse décimale.',lab:'(A⁻¹)₁₁ =',ans:0.75,tol:.001,hint:'C₁₁/det A.',why:'C₁₁ = 3 et det A = 4 : 3/4 = 0,75.'},
    {q:'d) Pour <i>m</i> = 2, quel est le coefficient (1, 3) de <i>A</i>⁻¹&nbsp;? Réponse décimale.',lab:'(A⁻¹)₁₃ =',ans:0.25,tol:.001,hint:'C’est C₃₁/det A, à cause de la transposée. C₃₁ : barre la ligne 3 et la colonne 1.',why:'C₃₁ = +det(1 0 ; 2 1) = 1, donc 1/4 = 0,25. Ici A est symétrique, donc C₁₃ = C₃₁ et la transposée ne change rien.'},
    {q:'e) Pour <i>m</i> = 2, quel est le coefficient (1, 2) de <i>A</i>⁻¹&nbsp;? Réponse décimale.',lab:'(A⁻¹)₁₂ =',ans:-0.5,tol:.001,hint:'C₂₁/det A, avec C₂₁ = −det(1 0 ; 1 2).',why:'C₂₁ = −(1 · 2 − 0 · 1) = −2, donc −2/4 = −0,5. Contrôle : ligne 1 de A, (2 1 0), fois colonne 1 de A⁻¹, (0,75 ; −0,5 ; 0,25) : 1,5 − 0,5 = 1.'},
   ],
   sol:'Selon la ligne 1, det A = m · (m² − 1) − 1 · (m − 0) = m³ − 2m = <b>m(m² − 2)</b>. A est singulière pour m = 0, √2, −√2, régulière sinon.<br>Pour m = 2, det A = 4 et les cofacteurs valent C₁₁ = 3, C₁₂ = −2, C₁₃ = 1, C₂₁ = −2, C₂₂ = 4, C₂₃ = −2, C₃₁ = 1, C₃₂ = −2, C₃₃ = 3. La comatrice est symétrique (comme A), donc<br><b>A⁻¹ = ¼ (3 −2 1 ; −2 4 −2 ; 1 −2 3) = (0,75 −0,5 0,25 ; −0,5 1 −0,5 ; 0,25 −0,5 0,75)</b>.<br>Contrôle : ligne 1 de A fois colonne 1 de A⁻¹ : 2 · 0,75 + 1 · (−0,5) = 1 ; fois colonne 2 : 2 · (−0,5) + 1 · 1 = 0.'},
  {kind:'Problème',h:'Le déterminant de la comatrice',
   p:'La formule <i>A</i> · ᵗcom(<i>A</i>) = det(<i>A</i>) I relie une matrice à sa comatrice. En prenant le déterminant des deux membres, on va découvrir la valeur de det(com <i>A</i>) pour une matrice 3 × 3 régulière. On commence par un cas très simple, la matrice diagonale <i>D</i> = diag(2, 3, 1), puis on généralise.',
   parts:[
    {q:'a) Que vaut det <i>D</i>&nbsp;?',lab:'det D =',ans:6,hint:'Matrice diagonale : produit de la diagonale.',why:'det D = 2 · 3 · 1 = 6.'},
    {q:'b) Calcule le cofacteur <i>C</i>₂₂ de <i>D</i>.',lab:'C₂₂ =',ans:2,hint:'Barre la ligne 2 et la colonne 2 : il reste diag(2, 1).',why:'C₂₂ = +det(2 0 ; 0 1) = 2. De même C₁₁ = 3 · 1 = 3 et C₃₃ = 2 · 3 = 6 ; les cofacteurs hors diagonale sont nuls.'},
    {q:'c) Que vaut det(com <i>D</i>)&nbsp;?',lab:'det(com D) =',ans:36,hint:'com D = diag(3, 2, 6).',why:'det(com D) = 3 · 2 · 6 = 36 = 6² = (det D)².'},
    {q:'d) Pour une matrice 3 × 3 régulière <i>A</i> quelconque, que vaut det(com <i>A</i>), et pourquoi&nbsp;?',opts:['det A, car la comatrice a les mêmes cofacteurs que A','(det A)², car det A · det(ᵗcom A) = det(det(A) I) = (det A)³ et det(ᵗcom A) = det(com A)','(det A)³, car det(det(A) I) = (det A)³','1/det A, car com A est liée à l’inverse'],ans:1,hint:'Prends le déterminant de A · ᵗcom(A) = det(A) I. À droite, det(A) I est une matrice 3 × 3 dont les trois coefficients diagonaux valent det A.',why:'det(A · ᵗcom A) = det A · det(ᵗcom A) et det(det(A) I) = (det A)³ (trois colonnes multipliées par det A). Donc det(ᵗcom A) = (det A)², et det(ᵗcom A) = det(com A) par le théorème de la transposée.'},
    {q:'e) Si <i>A</i> est une matrice 3 × 3 avec det <i>A</i> = 5, que vaut det(2 com <i>A</i>)&nbsp;?',lab:'det =',ans:200,hint:'det(2B) = 2³ det B, et det(com A) = (det A)².',why:'det(com A) = 25, puis det(2 com A) = 8 · 25 = 200.'},
   ],
   sol:'Pour D = diag(2, 3, 1), det D = 6 et com D = diag(3, 2, 6) (les cofacteurs hors diagonale contiennent une ligne nulle), donc det(com D) = 36 = (det D)².<br>En général, on prend le déterminant de A · ᵗcom(A) = det(A) I. À gauche, det A · det(ᵗcom A) ; à droite, det(det(A) I) = (det A)³ car chacune des trois colonnes de I est multipliée par det A. Pour A régulière on simplifie par det A ≠ 0 : det(ᵗcom A) = (det A)², puis det ᵗB = det B donne <b>det(com A) = (det A)²</b>.<br>Application : det A = 5 donne det(com A) = 25 et det(2 com A) = 2³ · 25 = <b>200</b>.<br>Remarque : la formule reste vraie pour une matrice singulière (det(com A) = 0), mais la preuve demande un autre argument.'},
]},
);
})();
